INSERT INTO `events` (`id`, `title`, `description`, `image`, `created_at`, `created_by`) VALUES
(3, 'ลูเกียเปิดตัวไดแมกซ์เป็นครั้งแรกโดยการทะยานลงมาจากท้องฟ้า!', 'สุดสัปดาห์แบตเทิลแมกซ์ลูเกียไดแมกซ์\nวันเสาร์ที่ 29 พฤศจิกายน เวลา 06.00 น. จนถึงวันอาทิตย์ที่ 30 พฤศจิกายน 2025 เวลา 21.00 น. ตามเวลาไทย\n\nเปิดตัวไดแมกซ์!\nโปเกมอนต่อไปนี้จะเปิดตัวแบบไดแมกซ์ใน Pokémon GO ในแบตเทิลแมกซ์ห้าดาว!\n\nลูเกียไดแมกซ์*\n* หากโชคดี อาจเจอตัวสีแตกต่างก็ได้!\n\nโบนัสอีเวนต์\nโบนัสต่อไปนี้จะเปิดใช้งานในระหว่างอีเวนต์\n\nขีดจำกัดการเก็บอนุภาคแมกซ์เพิ่มขึ้นเป็น 1,600\n1/4 ระยะทางการผจญภัยเพื่อรับอนุภาคแมกซ์*\nพาวเวอร์สป็อตจะรีเฟรชถี่ขึ้น\n8× อนุภาคแมกซ์จากพาวเวอร์สป็อต\n* หากต้องการใช้โบนัสนี้ คุณจะต้องรวบรวมอนุภาคแมกซ์ทั้งหมดที่มีอยู่ในเมนูใกล้เคียงก่อน เทรนเนอร์สามารถรวบรวมอนุภาคแมกซ์ได้ผ่านเมนูใกล้เคียงทุกวันโดยการสำรวจ แอดเวนเจอร์ซิงค์จะช่วยให้แน่ใจว่าระยะทางของคุณไม่เสียเปล่า! จับตาดูเมนูใกล้เคียงเพื่อหาไอคอนที่จะปรากฏขึ้นเมื่ออนุภาคแมกซ์พร้อมให้รวบรวมแล้ว\nงานวิจัยแบบจำกัดเวลาฟรี\nเทรนเนอร์จะมีโอกาสทำงานวิจัยแบบจำกัดเวลาได้ฟรี เริ่มตั้งแต่วันอังคารที่ 25 พฤศจิกายน 2025 เวลา 06.00 น. ตามเวลาไทย\n\nทำงานวิจัยแบบจำกัดเวลาให้เสร็จสิ้นเพื่อเผชิญหน้ากับโกสไดแมกซ์เพื่อสร้างทีมต่อสู้ของคุณให้สมบูรณ์แบบ และรับมือลูเกียไดแมกซ์! ภารกิจงานวิจัยแบบจำกัดเวลาจะมอบลูกอมโกส, อนุภาคแมกซ์ และอื่น ๆ อีกมากมายเพื่อช่วยเพิ่มพลังให้กับทีมต่อสู้ของคุณ\n\nโปรดทราบว่างานวิจัยแบบจำกัดเวลามีวันหมดอายุ ภารกิจที่เกี่ยวข้องกับงานวิจัยแบบจำกัดเวลาแบบฟรีนี้จะต้องเสร็จสิ้นและต้องรับรางวัลก่อนวันอาทิตย์ที่ 30 พฤศจิกายน 2025 เวลา 21.00 น. ตามเวลาไทย', 'https://lh3.googleusercontent.com/6nqooPPkdkv8phH6h3GupRBJE5lOVlaFiOUGBRzyt5G_EKhpIga2TjmKl-xMpmMb5F1ZKWpS7ce4-QenYWgxA-Ma9LJiAvBueA=e365-pa-nu-w1920', '2025-11-25 03:47:18', 1),
(4, 'คอมมิวนิตี้เดย์: สึสึเคระ', 'คอมมิวนิตี้เดย์พฤศจิกายน 2025: สึสึเคระ\nวันอาทิตย์ที่ 30 พฤศจิกายน 2025 ตั้งแต่ 14.00 น. ถึง 17.00 น. ตามเวลาไทย\n\nโปเกมอนนกหัวขวาน สึสึเคระ จะเป็นโปเกมอนเด่นในระหว่างคอมมิวนิตี้เดย์พฤศจิกายน!\n\nโปเกมอนเด่น\nสึสึเคระจะปรากฏตัวถี่ขึ้นในธรรมชาติ*\n\nหากโชคดี อาจเจอตัวสีแตกต่างหรือตัวที่มาพร้อมกับพื้นหลังพิเศษก็ได้!\nท่าโจมตีเด่น\nวิวัฒนาการเครารัปปา (ร่างวิวัฒนาการของสึสึเคระ) ระหว่างที่มีอีเวนต์หรือภายในสี่ชั่วโมงหลังจากนั้นเพื่อรับโดเดคาบาชิซึ่งรู้จักท่าโจมตีชาร์จจะงอยปากปืนใหญ่\n\nจะงอยปากปืนใหญ่\n\nเทรนเนอร์แบตเทิล: ความแรง 110\nยิมและการตีบอส: ความแรง 125\nเนื้อเรื่องงานวิจัยพิเศษคอมมิวนิตี้เดย์\nในราคา US$1.99 (หรือราคาเทียบเท่าสกุลเงินท้องถิ่นของคุณ) คุณจะสามารถเข้าถึงงานวิจัยพิเศษเฉพาะคอมมิวนิตี้เดย์สึสึเคระ ทำงานวิจัยนี้ให้เสร็จสิ้นเพื่อรับรางวัลให้มากยิ่งขึ้น รวมถึงสิ่งต่อไปนี้:\n\nการเผชิญหน้า 3 ครั้งกับสึสึเคระที่มาพร้อมกับพื้นหลังพิเศษธีมเรื่องเล่าแห่งการแปรเปลี่ยน\nการเผชิญหน้าเพิ่มเติมกับสึสึเคระ\nบัตรแบตเทิลพรีเมียม 1 ใบ\nลูกอมประหลาด XL 1 เม็ด\nและของแถมพิเศษอีกมากมาย!\n\nมีข้อจำกัดบางประการ ไม่สามารถมอบของขวัญได้หากผู้รับซื้อตั๋วงานวิจัยพิเศษหรือเคยได้รับของขวัญนี้แล้ว\nโบนัสอีเวนต์\n3× XP จากการจับโปเกมอน\n\n2× ลูกอมจากการจับโปเกมอน\n\nโอกาส 2× สำหรับเทรนเนอร์เลเวล 31 ขึ้นไปที่จะได้รับลูกอม XL จากการจับโปเกมอน\n\nเครื่องหอม (ยกเว้นเครื่องหอมรายวัน) ที่ใช้งานระหว่างอีเวนต์จะอยู่ได้นาน 3 ชั่วโมง\n\nถ่ายสแนปช็อตสักเล็กน้อยระหว่างคอมมิวนิตี้เดย์แล้วจะเจอเซอร์ไพรส์!\n\nอุปกรณ์ปล่อยลัวร์จะอยู่ได้นาน 1 ชั่วโมง และอาจดึงดูดโปเกมอนเด่นได้*\n\nสามารถแลกเปลี่ยนพิเศษได้เพิ่ม 1 ครั้ง สูงสุดถึง 3 ครั้งสำหรับวันนั้น*\n\nการแลกเปลี่ยนจะใช้สตาร์ดัสต์น้อยลง 50%*\n\nแม้ว่าโบนัสส่วนใหญ่จะใช้งานได้เฉพาะในช่วงระยะเวลาอีเวนต์สามชั่วโมงเท่านั้น แต่โบนัสเหล่านี้จะใช้งานได้ตั้งแต่เวลา 14.00 น. ถึง 21.00 น. ตามเวลาไทย\n\nโบนัสอุปกรณ์ปล่อยลัวร์\nตั้งแต่เวลา 14.00 น. ถึง 21.00 น. ตามเวลาไทย มีโอกาสสูงมากที่สึสึเคระจะปรากฏตัวที่เสาโปเกสต็อปที่มีอุปกรณ์ปล่อยลัวร์ทั่วไปเปิดใช้งานอยู่ สึสึเคระที่ถูกดึงดูดด้วยอุปกรณ์ปล่อยลัวร์ทั่วไปจะยังคงมีโอกาสเพิ่มขึ้นที่จะเป็นตัวสีแตกต่างและอาจมาพร้อมกับพื้นหลังพิเศษ นั่นหมายถึงโอกาสเพิ่มขึ้นที่จะได้เผชิญหน้ากับโปเกมอนเด่น แม้หลังจากเวลาอีเวนต์สิ้นสุดลง!', 'https://lh3.googleusercontent.com/bVcxjBqEJkt88b0bzoS31eSgv4moi__O2_rDrZW-J7BjSpGCgaGxJSpSBP91mkCrO0dPR-XeWjyGOGqlL9FKOaV9prBmnINFoQ=e365-pa-nu-w1920', '2025-11-25 03:49:26', 1),
(5, 'ปิดท้ายเรื่องเล่าแห่งการแปรเปลี่ยนด้วยอีเวนต์ช่วงเวลาแห่งศึกชี้ชะตา, ร่างแน่วแน่ของเคลดิโอ และการเปิดตัวสีแตกต่างของเคลดิโอ!', 'สรุปอีเวนต์: ช่วงเวลาแห่งศึกชี้ชะตา\nระยะเวลา: 25 - 30 พ.ย. 2025 (10.00 - 20.00 น.)\nไฮไลท์สำคัญ:\n- เปิดตัว เคลดิโอ (ร่างแน่วแน่) ครั้งแรก\n- วิธีเปลี่ยนร่าง: ใช้ลูกอมเคลดิโอ 50 เม็ด (ปลดล็อกผ่านงานวิจัยพิเศษส่วนสุดท้าย)\n- ท่าพิเศษ: เรียนรู้ท่า \"ดาบลึกลับ\" (Secret Sword)\nหมายเหตุ: ต้องกดรับงานวิจัยพิเศษภายใน 2 ธ.ค. 2025 (10.00 น.)', 'https://lh3.googleusercontent.com/V1RFaeLq3H8dCjoHfgThoVHecJijY-JLVtln5N_g6dPbqu5Xb8GK3XIB6KjvXZeo_yfNqsUusl3bcUKK2jyMRmdM-tXwVq1OB8Sn=e365-pa-nu-w1920', '2025-11-25 06:16:12', 1),
(6, 'อัปเดตโกแบตเทิลลีก: เส้นทางล่าสมบัติ', 'โกแบตเทิลลีก: เส้นทางล่าสมบัติ จะเริ่มขึ้นในวันอังคารที่ 2 ธันวาคม 2025 เวลา 13.00 น. PDT (GMT −7)\nสิ่งต่อไปนี้จะเกิดขึ้นในช่วงต้นฤดูกาล\nรับรางวัลเมื่อสิ้นสุดฤดูกาลได้ในหน้าจอการต่อสู้\nระดับโกแบตเทิลลีกของคุณจะถูกรีเซ็ต\nข้อกำหนดในการเพิ่มระดับจะยังคงเหมือนกับในฤดูกาลก่อนหน้า\nกำหนดการโกแบตเทิลลีก: เส้นทางล่าสมบัติ\nลีกต่อไปนี้จะเริ่มและสิ้นสุดเวลา 13.00 น. PDT (GMT −7) ตามวันที่ด้านล่างนี้', 'https://lh3.googleusercontent.com/RWNG582mmAJV1F1RbAkkOS9FkiO-4dW2Q0v7-XlssV4ztIOR3qySldKcweMYLRmVf2c4M3LfAa0sPd2JeE3zMaG_rVK1qJiiwYvQ=e365-pa-nu-w1920', '2025-12-02 04:04:59', 1),
(7, 'ออกเดินทางสู่การผจญภัยในพัลเดียในอีเวนต์ การเดินทางในภูมิภาคพัลเดีย!', 'อีเวนต์ภูมิภาคพัลเดียจัดวันที่ 2–9 ธ.ค. 2025 พร้อมเปิดตัวโคจีโอ ไลน์วิวัฒนาการครบ\nโบนัส: 2× XP ตีบอส, 2× XP วิวัฒนาการ และโอกาสเจอโยกิราส/ทัทซึเบสีแตกต่างเพิ่มขึ้น\nเผชิญหน้าในธรรมชาติใหม่ เช่น มาเมะบัตตะ พาโม มินีฟ และมีวันสลับโปเกมอนเด่น\nตีบอส 3 ดาวมีเคนเทารอสพัลเดียทุกร่าง, โอโตชิโดริ และเฮรัชเชอร์\nมีงานวิจัยภาคสนาม, คำท้านักสะสม และงานวิจัยจำกัดเวลาแบบเสียเงิน (รางวัลสตาร์ดัสต์/พรีเมียมพาส/เจอโปเกมอนธีม)', 'https://lh3.googleusercontent.com/6VWnagFi2rsW0vaNLVWFLdpEpJla0YlutIqenhRWflYI8l05LDAmrA79t7QLLcYhYwUZCejY-_Dam5XIgoH9At9184MnlB-KAJfP=e365-pa-nu-w1920', '2025-12-02 04:08:18', 1),
(8, 'พัลเกียและเครื่องฟักไข่จำกัดเวลากลับมาอีกครั้งในบัตรผ่าน GO: ธันวาคม!', 'บัตรผ่าน GO: ธันวาคม เปิดใช้งาน 2 ธ.ค. 2025–6 ม.ค. 2026 และสามารถเก็บแต้มได้ไม่จำกัดในวันที่ 3–4 ม.ค.\nอัปเกรดเป็น GO Deluxe ราคา $7.99 หรือ Deluxe + 10 ระดับ ราคา $9.99 เพื่อรับรางวัลมากขึ้นและเลื่อนระดับไวขึ้น\nซื้อผ่าน Web Store จะได้ของขวัญเพิ่ม เช่น ไฮเปอร์บอล, ยาคืนชีพ, พรีเมียมพาส และกล่องใหญ่พิเศษแบบเฉพาะเว็บ\nรางวัลรวม: เผชิญหน้าพัลเกีย, สตาร์ดัสต์, XP, อนุภาคแมกซ์ และไอเท็มพรีเมียม พร้อมโบนัสเมื่อถึงระดับ 25/50/75\nGO Deluxe มีเครื่องฟักไข่จำกัดเวลาที่ใช้ไม่จำกัดจนถึง 13 ม.ค. 2026 และโบนัสเปิด/รับของขวัญมากกว่าเวอร์ชันฟรี', 'https://lh3.googleusercontent.com/5lezZDzzpWfYHX-jkeY29-bBUlKDam8g4Hv7TSJ0JJX0z0vjbW62FSqhTnZxyc8_LeoM0fD6Ri85YUzFAPIoiw9NZV2k6MsfbBpE=e365-pa-nu-w1920', '2025-12-02 04:09:33', 1),
(9, 'ฝึกฝนและรับมือกับคำท้าสำหรับทั่วโลกในระหว่างอีเวนต์ ออกหมัดแล้วเตะ!', 'อีเวนต์ “ออกหมัดแล้วเตะ” จัดวันที่ 11–16 ธ.ค. 2025 พร้อมโบนัส 2× ลูกอมจับโปเกมอน และโอกาสเจอซาวามูลาร์/เอบิวาลาร์ไดแมกซ์สีแตกต่างเพิ่มขึ้น\nมีคำท้าทั่วโลก: ทำแบตเทิลแมกซ์รวมให้ครบเพื่อปลดล็อกทาทักโกะ (เปิดตัวใหม่), โคโจฟู/จาราโคธรรมชาติ, และลูกอมเพิ่มจากแมกซ์\nโปเกมอนธรรมชาติเด่นได้แก่ เนียวโรโมะ, วันริกี, มาคุโนชิตะ และออคตัน (มีโอกาสสีแตกต่าง)\nงานวิจัยภาคสนามให้ TM ต่าง ๆ และการเจอซาวามูลาร์/เอบิวาลาร์ไดแมกซ์\nงานวิจัยจำกัดเวลาแบบเสียเงินราคา $1.99 มีรางวัลลูกอมประหลาด, ลูกอม XL, อนุภาคแมกซ์ และต้องทำให้เสร็จภายใน 16 ธ.ค. 2025', 'https://lh3.googleusercontent.com/ksuG-r5m6PVf9_6ksXCfcB50tGNX63FkA3lFM4Jaka0KpXIbqvvKikuOELd4gcZv4a8X87crL2Aq4gMuX-gZAV2LfE7-1iZSyA=e365-pa-nu-w1920', '2025-12-02 04:11:16', 1),
(10, 'คาบิกอนกิกะแมกซ์กลับมาอีกครั้งในวันแบตเทิลแมกซ์ส่งท้ายปี!', 'วันแบตเทิลแมกซ์คาบิกอนกิกะแมกซ์\nวันอาทิตย์ที่ 14 ธันวาคม 2025 ตั้งแต่ 14.00 น. ถึง 17.00 น. ตามเวลาไทย\n\nโปเกมอนเด่น\nคาบิกอนกิกะแมกซ์*\n\nหากโชคดี อาจเจอตัวสีแตกต่างก็ได้!\nโบนัสอีเวนต์\nโบนัสต่อไปนี้จะเปิดใช้งานในระหว่างอีเวนต์\n\nขีดจำกัดการเก็บอนุภาคแมกซ์เพิ่มขึ้นเป็น 1,600\nพาวเวอร์สป็อตทั้งหมดจะมีแบตเทิลกิกะแมกซ์\nพาวเวอร์สป็อตจะรีเฟรชถี่ขึ้น\n8× อนุภาคแมกซ์จากพาวเวอร์สป็อต\nแลกเปลี่ยนแบบพิเศษเพิ่มเติม 2 ครั้ง\nตั้งแต่วันที่ 14 ธันวาคม เวลา 08.00 น. ถึงวันที่ 15 ธันวาคม เวลา 11.00 น. ตามเวลาไทย ขีดจำกัดตีบอสระยะไกลรายวันจะเพิ่มจาก 10 ครั้งเป็น 20 ครั้ง\nโบนัสต่อไปนี้จะเปิดใช้งานในวันที่ 14 ธันวาคม 2025 ตั้งแต่เวลา 00.00 น. ถึง 17.00 น. ตามเวลาไทย\n\n2× อนุภาคแมกซ์จากการสำรวจ*\n\n1/4 ระยะทางการผจญภัยเพื่อรับอนุภาคแมกซ์*\n\nคุณสามารถรวบรวมอนุภาคแมกซ์ทั้งหมดที่มีอยู่ในเมนูใกล้เคียงก่อน เทรนเนอร์สามารถรวบรวมอนุภาคแมกซ์ได้ผ่านเมนูใกล้เคียงทุกวันโดยการสำรวจ แอดเวนเจอร์ซิงค์จะช่วยให้แน่ใจว่าระยะทางของคุณไม่เสียเปล่า! จับตาดูเมนูใกล้เคียงเพื่อหาไอคอนที่จะปรากฏขึ้นเมื่ออนุภาคแมกซ์พร้อมให้รวบรวมแล้ว\n\nหากต้องการใช้โบนัสเหล่านี้ คุณจะต้องรวบรวมอนุภาคแมกซ์ทั้งหมดที่มีอยู่ในเมนูใกล้เคียงก่อน\n\nงานวิจัยแบบจำกัดเวลา\nจะมีงานวิจัยแบบจำกัดเวลาที่จะนำไปสู่อีเวนต์\n\nทำงานวิจัยแบบจำกัดเวลาให้เสร็จสิ้นเพื่อเผชิญหน้ากับโปเกมอนไดแมกซ์ ซึ่งเป็นคู่แข่งที่แข็งแกร่งในการต่อสู้กับคาบิกอนกิกะแมกซ์! ภารกิจเหล่านี้จะมอบลูกอมและอนุภาคแมกซ์เพื่อช่วยเสริมพลังให้กับทีมของคุณ\n\n8 ธันวาคม เวลา 06.00 น. – 14 ธันวาคม เวลา 17.00 น. ตามเวลาไทย**\nวันริกีไดแมกซ์*\n\nหากโชคดี อาจเจอตัวสีแตกต่างก็ได้!\nตั๋วอีเวนต์\nในราคา US$4.99 (หรือราคาเทียบเท่าสกุลเงินท้องถิ่นของคุณ) คุณจะสามารถเข้าถึงงานวิจัยแบบจำกัดเวลาเฉพาะอีเวนต์\n\nงานวิจัยแบบจำกัดเวลารวมถึงสิ่งต่อไปนี้\n\nไดมัชรูม 1 อัน\n25,000 XP\nคุณจะได้รับโบนัสต่อไปนี้ด้วย\n\n2× XP จากแบตเทิลแมกซ์\nขีดจำกัดการรวบรวมอนุภาคแมกซ์เพิ่มเป็น 5,600\nงานวิจัยแบบจำกัดเวลานี้จะมีผลในวันอาทิตย์ที่ 14 ธันวาคม 2025 ตั้งแต่ 14.00 น. ถึง 17.00 น. ตามเวลาไทย\n\nเทรนเนอร์ทุกคนจะสามารถซื้อและมอบตั๋วเป็นของขวัญให้กับเพื่อน Pokémon GO ที่มีระดับความสนิทสนมเป็นเพื่อนสนิทขึ้นไปอีกด้วย โปรดทราบว่าการซื้อ—รวมถึงการซื้อให้เทรนเนอร์คนอื่น—ไม่สามารถขอคืนเงินได้ (ขึ้นอยู่กับกฎหมายที่บังคับใช้และข้อยกเว้นที่กำหนดไว้ในข้อกำหนดในการให้บริการ) ไม่สามารถใช้โปเกคอยน์ซื้อตั๋วได้\n\nโปรดทราบว่าตั๋วจะวางจำหน่ายเฉพาะในร้านค้าในเกมเท่านั้น จนถึงวันอาทิตย์ที่ 14 ธันวาคม 2025 เวลา 17.00 น. ตามเวลาไทย\n\nการนัดเข้าร่วม (RSVP) แบตเทิลกิกะแมกซ์\nประสานงานกับเพื่อน, ครอบครัว และเทรนเนอร์คนอื่น ๆ ในชุมชนของคุณ และทั่วโลกได้ง่ายขึ้น เพื่อร่วมสนุกในการตีบอสและแบตเทิลกิกะแมกซ์ด้วยกัน!\n\nไปที่โพสต์บล็อกนัดเข้าร่วม (RSVP) เพื่อเรียนรู้เพิ่มเติมเกี่ยวกับฟีเจอร์นี้!\n\nเพิ่มโอกาสให้เต็มแมกซ์เพื่อชัยชนะด้วย Campfire!\nCampfire ทำให้การค้นหาแบตเทิลแมกซ์และเทรนเนอร์อื่น ๆ เป็นเรื่องง่ายกว่าที่เคย และจะช่วยให้คุณเอาชนะพวกมันได้ ดูกิจกรรมแบตเทิลแมกซ์และไฟที่อยู่ใกล้เคียงภายใน Pokémon GO ได้โดยแตะไอคอนสีเขียวใต้เข็มทิศที่มุมขวาบนของมุมมองแผนที่ และตรวจสอบการพบปะออนไลน์บนแผนที่ Campfire!\n\nPokemon GO Web Store - กล่องตั๋วชั้นยอดสุดสัปดาห์แบตเทิลแมกซ์คาบิกอนกิกะแมกซ์\nกล่องตั๋วชั้นยอดสุดสัปดาห์แบตเทิลแมกซ์คาบิกอนกิกะแมกซ์จะวางจำหน่ายในราคา US$4.99 (หรือราคาเทียบเท่าสกุลเงินท้องถิ่นของคุณ) และประกอบด้วยตั๋วอีเวนต์และโบนัสบัตรแบตเทิลพรีเมีย!\n\nตรวจสอบได้ใน Pokémon GO Web Store!\n\nไดมัชรูม\nไดมัชรูมเป็นไอเท็มที่เพิ่มแดเมจทั้งหมดที่โปเกมอนไดแมกซ์และกิกะแมกซ์สร้างในแบตเทิลแมกซ์เป็นสองเท่าชั่วคราว สามารถใช้ไดมัชรูมหลายชิ้นติดต่อกันเพื่อเพิ่มระยะเวลาของเอฟเฟกต์ได้ แต่จะไม่เพิ่มตัวคูณแดเมจ\n\nคุณสามารถใช้ไดมัชรูมจากกระเป๋าเก็บไอเท็มของคุณได้ในขณะที่อยู่ในล็อบบี้แบตเทิลแมกซ์ นอกจากนี้ คุณยังสามารถดูได้ว่าเทรนเนอร์คนอื่นในล็อบบี้ได้เปิดใช้งานไดมัชรูมแล้วหรือไม่', 'https://lh3.googleusercontent.com/y7aZmUU4GcZTYGUv7JEMP_ACZ1fXq1bVP9xPkjhxE852n8xAYGjSxFa-bIZRNGVOVQoRhcRyNIZdeROlltDxyhdTjWHm8xsmB_c=e365-pa-nu-w1920', '2025-12-09 02:03:07', 1),
(11, 'ร่วมฉลองวันหยุดกับโปเกมอนสวมชุดคอสตูมใหม่ในระหว่างวินเทอร์ฮอลิเดย์ - 1!', 'วินเทอร์ฮอลิเดย์ - 1\nวันพฤหัสที่ 18 ธันวาคม เวลา 10.00 น. ถึงวันพุธที่ 24 ธันวาคม 2025 เวลา 10.00 น. ตามเวลาไทย\n\nโปเกมอนเปิดตัวใหม่\nโปเกมอนในชุดคอสตูมใหม่จะปรากฏตัวระหว่างอีเวนต์นี้!\n\nอุซกกีสวมชุดฮอลิเดย์*\nเด็นจิมูชิสวมชุดฮอลิเดย์*\nคุวากานอนสวมชุดฮอลิเดย์^\n\nหากโชคดี อาจเจอตัวสีแตกต่างก็ได้!\n^ในขณะที่คุณอยู่ใกล้กับอุปกรณ์ปล่อยลัวร์แม่เหล็กที่ทำงานอยู่ คุณสามารถใช้ลูกอมอโกจิมูชิ 100 เม็ดเพื่อวิวัฒนาการ เด็นจิมูชิสวมชุดฮอลิเดย์ เป็น คุวากานอนสวมชุดฮอลิเดย์\nโบนัสอีเวนต์\nโอกาสเพิ่มขึ้นที่จะฟัก สีแตกต่างพิชูสวมหมวกซานต้า และคูมะชุนติดโบออกจากไข่ 7 กม.\nนอกจากนี้ บรรลุความสำเร็จขั้นใหญ่ในบัตรผ่าน GO: วินเทอร์ฮอลิเดย์ 2025 เพื่อปลดล็อกโบนัสต่อไปนี้\n\nTier 1\n\n2× XP จากการส่งของขวัญ\nบัตรผ่าน GO Deluxe: 2× สตาร์ดัสต์จากการเปิดของขวัญ\nTier 2\n\nอาจได้รับไอเท็มเป็นรางวัลเพิ่มเติมจากการเปิดของขวัญ\nบัตรผ่าน GO Deluxe: ระยะทางฟักไข่ 1/2 เมื่อไข่ถูกวางไว้ในเครื่องฟักไข่ระหว่างช่วงเวลาอีเวนต์\nTier 3\n\nXP เพิ่มอีก 50% สำหรับการชนะแบตเทิลตีบอส\nบัตรผ่าน GO Deluxe: 2× XP จากการจับโปเกมอน\nเผชิญหน้าในธรรมชาติ\nคุณอาจได้เผชิญหน้ากับโปเกมอนธีมอีเวนต์ในธรรมชาติ รวมถึง อุริมู*, ยูกิวาราชิ*, ทามาซาราชิ* และโปเกมอนอื่น ๆ อีกมากมาย! และอาจได้เผชิญหน้ากับ อุซกกีสวมชุดฮอลิเดย์* และ เด็นจิมูชิสวมชุดฮอลิเดย์*!\n\n*หากโชคดี อาจเจอตัวสีแตกต่างก็ได้!\nไข่\nโปเกมอนต่อไปนี้จะฟักออกจากไข่ 7 กม.\n\nพิชูสวมหมวกซานต้า*\nมุจูล*\nคูมะชุนติดโบ*\nฟรีจิโอ*\nยูกิฮามิ\n\n* หากโชคดี อาจเจอตัวสีแตกต่างก็ได้!\nตีบอส\nโปเกมอนต่อไปนี้จะปรากฏตัวในการตีบอส\n\nตีบอสสามดาว\nอุซกกีสวมชุดฮอลิเดย์*\nเครเบส (ร่างฮิซุย)*\nเด็นจิมูชิสวมชุดฮอลิเดย์*\n\n*หากโชคดี อาจเจอตัวสีแตกต่างก็ได้!\nไอเท็มอวาตาร์ใหม่\nสามารถซื้อไอเท็มอวาตาร์ต่อไปนี้ได้จากร้านค้าในเกมระหว่างอีเวนต์นี้ และจะยังคงซื้อได้หลังจากอีเวนต์สิ้นสุดลงแล้ว!\n\nกระเป๋าเด็นจิมูชิ\nเสื้อไหมพรมฮอลิเดย์อุซกกี\n\n\nการเผชิญหน้างานวิจัยภาคสนาม\nภารกิจงานวิจัยภาคสนามธีมอีเวนต์จะพร้อมให้ใช้งาน\n\nทำภารกิจงานวิจัยภาคสนามให้เสร็จสิ้นเพื่อรับสตาร์ดัสต์และการเผชิญหน้ากับโปเกมอนธีมอีเวนต์\n\nบัตรผ่าน GO: วินเทอร์ฮอลิเดย์ 2025\nตั้งแต่วันพฤหัสที่ 18 ธันวาคม เวลา 10.00 น. ถึงวันจันทร์ที่ 29 ธันวาคม 2025 เวลา 20.00 น. ตามเวลาไทย บัตรผ่าน GO และบัตรผ่าน GO Deluxe สำหรับวินเทอร์ฮอลิเดย์ - 1 และ 2 ที่มาใหม่จะวางจำหน่ายใน Pokémon GO!\n\nบัตรผ่าน GO และบัตรผ่าน GO Deluxe\nบัตรผ่าน GO คือแทร็กความคืบหน้าฟรีแบบจำกัดเวลาที่เปิดให้ใช้งานในช่วงระยะเวลาที่กำหนด การเก็บแต้ม GO จะช่วยให้เพิ่มระดับเพื่อรับรางวัล\n\nเทรนเนอร์จะได้รับบัตรผ่าน GO: วินเทอร์ฮอลิเดย์ 2025 โดยอัตโนมัติในวันพฤหัสที่ 18 ธันวาคม เวลา 10.00 น. ตามเวลาไทย คุณสามารถเก็บสะสมแต้ม GO และเลื่อนระดับเพื่อรับรางวัลเพิ่มเติมได้จนถึงวันจันทร์ที่ 29 ธันวาคม 2025 เวลา 20.00 น. ตามเวลาไทย\n\nในราคา US$7.99* คุณสามารถอัปเกรดเป็นบัตรผ่าน GO Deluxe ซึ่งเป็นเวอร์ชันเสียเงินของบัตรผ่าน GO ที่มอบรางวัลที่อัปเกรดขึ้นและความคืบหน้าที่รวดเร็วยิ่งขึ้น\n\nในราคา US$9.99* คุณสามารถอัปเกรดเป็นบัตรผ่าน GO Deluxe + 10 ระดับเพื่อรับแต้ม GO มากพอที่จะไปถึงระดับ 11 โดยอัตโนมัติ\n\nในขณะที่กำลังคืบหน้าผ่านบัตรผ่าน GO Deluxe คุณจะสามารถรับรางวัลทั้งหมดจากทั้งบัตรผ่าน GO ฟรีและบัตรผ่าน GO Deluxe คุณสามารถอัปเกรดเป็นบัตรผ่าน GO Deluxe ได้ตลอดเวลาและยังรับรางวัลจากระดับที่เคยปลดล็อกไว้ก่อนหน้านี้ได้อีกด้วย\n\nรางวัลที่ปลดล็อกในบัตรผ่าน GO จะหมดอายุในวันจันทร์ที่ 29 ธันวาคม 2025 เวลา 23.59 น. ตามเวลาไทย ดังนั้นอย่าลืมรับรางวัลของคุณก่อนที่รางวัลจะหายไป!\n\n* ราคาทั้งหมดที่ระบุไว้เป็นหน่วยดอลลาร์สหรัฐหรือราคาเทียบเท่าสกุลเงินท้องถิ่นของคุณ\nโปเกมอนเด่นและรางวัล\nทำภารกิจบัตรผ่านให้เสร็จสิ้นเพื่อเลื่อนระดับบัตรผ่าน GO ของคุณแล้วรับรางวัลต่อไปนี้\n\nการเผชิญหน้ากับยูกิฮามิ\nการเผชิญหน้ากับโปเกมอนธีมอีเวนต์\nสตาร์ดัสต์\nXP\nมอนสเตอร์บอล\nลูกอม\nและของแถมอีกมากมาย!\nเทรนเนอร์ที่อัปเกรดเป็นบัตรผ่าน GO Deluxe จะได้รับรางวัลต่อไปนี้ด้วย\n\nหมวกไหมพรมยูกิฮามิ\nการเผชิญหน้าเพิ่มเติมกับโปเกมอนธีมอีเวนต์เพิ่มเติม!\nบัตรแบตเทิลพรีเมียม\nลูกอมประหลาด XL\nลูกอม XL\nและของแถมอีกมากมาย!\n\nPokémon GO Web Store\nบัตรผ่าน GO Deluxe คือบัตรผ่าน GO เวอร์ชันเสียเงิน สามารถซื้อได้ใน Pokémon GO Web Store แล้ว! บัตรผ่าน GO Deluxe ของคุณที่ซื้อผ่าน Pokémon GO Web Store จะเปิดใช้งานทันทีที่บัตรผ่าน GO เริ่มต้น\n\nเทรนเนอร์ที่อัปเกรดเป็น บัตรผ่าน GO Deluxe: วินเทอร์ฮอลิเดย์ 2025 หรือ บัตรผ่าน GO Deluxe: วินเทอร์ฮอลิเดย์ 2025 + 10 ระดับ ใน Pokémon GO Web Store จะได้รับไฮเปอร์บอล 10 ลูก, ยาคืนชีพชั้นยอด 5 ชิ้น, บัตรแบตเทิลพรีเมียม 1 ใบ และยาฟื้นพลังกายเต็มถัง 5 ชิ้นเป็นของขวัญจากการซื้อ\n\nหรือตุนของจำเป็นไว้พร้อม ๆ กับการอัปเกรดของคุณด้วย กล่องไฮเปอร์บัตรผ่าน GO Deluxe: วินเทอร์ฮอลิเดย์ 2025 + 10 ระดับ พิเศษเฉพาะบนเว็บ ซึ่งรวมถึงไฮเปอร์บอล 20 ลูก, ยาคืนชีพชั้นยอด 10 ชิ้น, ยาฟื้นพลังกายเต็มถัง 10 ชิ้น, บัตรแบตเทิลพรีเมียม 2 ใบ, เครื่องฟักไข่ 1 เครื่อง และเครื่องฟักไข่ชั้นเยี่ยม 1 เครื่องเป็นของขวัญเมื่อซื้อสินค้า!', 'https://lh3.googleusercontent.com/1XIa5cjHtAIl_GCzuw7_nsCYqjYcc0Gt-4mV7J4ECyq9ekwgDRmGssQruUuTyF8dzvh6yhglOe14WZinrNR8TW9H4GINI2qg72Y=e365-pa-nu-w1920', '2025-12-09 02:04:09', 1),
(12, 'แลกเปลี่ยนระยะไกลกับ \"เพื่อนแท้ตลอดไป\"!', 'ระดับมิตร \"เพื่อนแท้ตลอดไป\" และการ \"แลกเปลี่ยนระยะไกล\" จะเริ่มเปิดให้ใช้ทีละขั้น เริ่มตั้งแต่วันจันทร์ที่ 8 ธันวาคม 2025 (ตามเวลาแปซิฟิค) โดยเริ่มจากที่นิวซีแลนด์ เราจะแจ้งรายละเอียดเพิ่มเติมอีกครั้งเมื่อฟีเจอร์นี้เปิดให้เล่นได้ทั่วโลกหลังจากนี้ คอยติดตามนะ!\nเทรนเนอร์ทุกท่าน\n\nเตรียมตัวเพิ่มระดับมิตรภาพใน Pokémon GO ได้เลย! ทุกคนจะสามารถเพิ่มระดับของมิตรภาพขั้นใหม่ล่าสุด นั่นก็คือ “เพื่อนแท้ตลอดไป” เมื่อคุณกลายเป็น”เพื่อนแท้ตลอดไป”แล้ว คุณจะสามารถ “แลกเปลี่ยนระยะไกล” ซึ่งคุณสามารถใช้เพื่อแลกเปลี่ยนโปเกมอนกับเพื่อนคนนั้นได้จากทุกที่!\n\nเป็น \"เพื่อนแท้ตลอดไป\"\nเทรนเนอร์ทุกท่านสามารถบรรลุระดับมิตรภาพใหม่ได้แล้ว…”เพื่อนแท้ตลอดไป”! ระดับมิตรภาพใหม่ที่สูงขึ้นนี้ (เหนือกว่าระดับเพื่อนแท้) จะมอบรางวัลและ XP พร้อมสิทธิพิเศษใหม่สองอย่าง\n\nเมื่อคุณกลายเป็น “เพื่อนแท้ตลอดไป” กับเทรนเนอร์อื่น คุณจะสามารถแลกเปลี่ยนระยะไกลร่วมกันได้!\nคุณสามารถร่วมสนุกกับ “เพื่อนแท้ตลอดไป” ของคุณเพื่อรับแต้มมิตรภาพได้เรื่อย ๆ ยิ่งสะสมแต้มมิตรภาพได้มากเท่าไหร่ ก็ยิ่งได้รับรางวัลมากขึ้นเท่านั้น รวมถึง XP และแลกเปลี่ยนระยะไกลเพิ่มเติม แต่โปรดทราบว่าเทรนเนอร์แต่ละคนสามารถ “แลกเปลี่ยนระยะไกล” ได้เพียงครั้งเดียวกับ “เพื่อนแท้ตลอดไป” แต่ละคน ดังนั้นควรพิจารณาการแลกเปลี่ยนให้ดีก่อนที่จะสะสมแต้มมิตรภาพได้มากพอสำหรับการแลกเปลี่ยนครั้งต่อไป\nสำหรับข้อมูลเพิ่มเติม โปรดดูบทความศูนย์ช่วยเหลือ Pokémon GO เกี่ยวกับรายชื่อเพื่อนและระดับมิตรภาพ\n\nแต้มมิตรภาพ\nแต้มมิตรภาพเป็นวิธีใหม่ในการติดตามความคืบหน้าของมิตรภาพกับเทรนเนอร์คนอื่น ๆ เทรนเนอร์ทุกท่านสามารถรับแต้มมิตรภาพได้สูงสุด 1 แต้มต่อวันกับเพื่อนแต่ละคน โดยการแบตเทิล แลกเปลี่ยน ส่งของขวัญ หรือทำกิจกรรมอื่น ๆ ร่วมกัน\n\nนอกจากนี้ คุณยังสามารถรับแต้มมิตรภาพเพิ่มเติมได้จากการทำคำท้ารายสัปดาห์ร่วมกัน\n\nสำหรับข้อมูลเพิ่มเติม โปรดดูบทความศูนย์ช่วยเหลือ Pokémon GO เกี่ยวกับรายชื่อเพื่อนและระดับมิตรภาพ\n\nแลกเปลี่ยนระยะไกล\nเพื่อเตรียมพร้อมสำหรับการ “แลกเปลี่ยนระยะไกล” ครั้งแรกของคุณ คุณจะถูกขอให้ใช้แท็กแลกเปลี่ยนระยะไกลพิเศษเพื่อทำเครื่องหมายโปเกมอนที่คุณยินดีจะแลกเปลี่ยนกับ”เพื่อนแท้ตลอดไป”ของคุณ เมื่อคุณกลายเป็น”เพื่อนแท้ตลอดไป”กับใครคนหนึ่งแล้ว ทั้งสองคนจะสามารถเห็นโปเกมอนที่อีกฝ่ายได้ทำเครื่องหมายไว้ด้วยแท็กแลกเปลี่ยนระยะไกล ซึ่งก็คือโปเกมอนที่พวกเขายินดีจะแลกเปลี่ยน\n\nหากต้องการเริ่มต้นการ “แลกเปลี่ยนระยะไกล” เทรนเนอร์แต่ละคนจะผลัดกันเลือกโปเกมอนที่เพื่อนของตนติดแท็กไว้สูงสุด 3 ตัว “รายชื่อโปเกมอนที่ต้องการ” นี้จะถูกส่งไปให้เทรนเนอร์อีกคน เทรนเนอร์แต่ละคนจะเลือกโปเกมอนที่เพื่อนขอมา 1 ตัวเพื่อมอบให้กับอีกฝ่าย จากนั้นเทรนเนอร์ทั้งสองจะตรวจสอบข้อเสนอสุดท้ายและมีสิทธิ์ยืนยันหรือยกเลิก ตลอดกระบวนการ “แลกเปลี่ยนระยะไกล” เทรนเนอร์แต่ละคนมีตัวเลือกที่จะปฏิเสธคำขอปัจจุบันและเริ่มกระบวนการใหม่\n\nหากพวกคุณเป็นเพื่อนนำโชคของกันและกัน การแลกเปลี่ยนครั้งต่อไปจะเป็นการแลกเปลี่ยนนำโชค แม้ว่าจะเป็นการ “แลกเปลี่ยนระยะไกล” ก็ตาม!* และการแลกเปลี่ยนระยะไกลจะไม่นับเป็นการแลกเปลี่ยนแบบพิเศษ ไม่ว่าจะแลกเปลี่ยนโปเกมอนตัวใดก็ตาม\n\nโปเกมอนต่อไปนี้จะไม่นับรวมในการ “แลกเปลี่ยนระยะไกล”\n\nโปเกมอนที่จับได้ในช่วง 30 วันที่ผ่านมา\nโปเกมอนที่เคยแลกเปลี่ยนมาก่อน\nโปเกมอนชาโดว์\nโปเกมอนมายา\nโปเกมอนป้องกันยิมหรือพาวเวอร์สป็อต\nโปเกมอนที่ปัจจุบันถูกตั้งเป็นคู่หูของคุณ\nโปเกมอนที่วิวัฒนาการเมก้าอยู่\nโปเกมอนรวมร่าง\nซาเชียน (ราชาแห่งดาบ) และซามาเซนตา (ราชาแห่งโล่)\nโปเกมอนที่ถูกวางไว้ที่สนามเด็กเล่นโปเกมอน\nสำหรับข้อมูลเพิ่มเติม โปรดดูบทความศูนย์ช่วยเหลือ Pokémon GO เกี่ยวกับการแลกเปลี่ยนโปเกมอน\n\nเมื่อคุณได้รับโปเกมอนนำโชคจากการ “แลกเปลี่ยนระยะไกล” แล้ว คุณจะเลิกเป็นเพื่อนนำโชคกัน\nคำท้ารายสัปดาห์\nคำท้ารายสัปดาห์จะให้โอกาสคุณได้รวมทีมกับเทรนเนอร์คนอื่น ๆ สูงสุด 3 คนจากรายชื่อเพื่อนของคุณ ไม่ว่าพวกเขาจะอยู่ที่ไหนก็ตาม เพื่อรับคำท้าแบบกลุ่มในแต่ละสัปดาห์ คุณสามารถรับรางวัลมากมาย รวมถึง XP และแต้มมิตรภาพเพิ่มเติม\n\nการอัปเดตเพิ่มเติม\nจำนวนเพื่อนสูงสุดจะเพิ่มจาก 450 เป็น 650 ภายในไม่กี่สัปดาห์ข้างหน้า โดยจะเพิ่มครั้งละ 50 คน\nงานวิจัยแบบจำกัดเวลา\nเทรนเนอร์จะมีโอกาสทำงานวิจัยแบบจำกัดเวลาได้ฟรี เริ่มตั้งแต่วันจันทร์ที่ 15 ธันวาคม เวลา 10.00 น. ถึงวันจันทร์ที่ 29 ธันวาคม 2025 เวลา 20.00 น. ตามเวลาไทย\n\nทำงานวิจัยแบบจำกัดเวลาให้เสร็จสิ้นเพื่อเผชิญหน้ากับโคฟูคิมูชิ ภารกิจงานวิจัยแบบจำกัดเวลาจะมอบ XP, สตาร์ดัสต์ และอื่น ๆ อีกมากมาย!\n\nโปรดทราบว่างานวิจัยแบบจำกัดเวลามีวันหมดอายุ ภารกิจที่เกี่ยวข้องกับงานวิจัยแบบจำกัดเวลานี้จะต้องเสร็จสิ้นและต้องรับรางวัลก่อนวันอาทิตย์ที่ 4 มกราคม 2026 เวลา 20.00 น. ตามเวลาไทย', 'https://lh3.googleusercontent.com/OYTYug-CJl0JMIub38A44t8hl9P-L53EnN9em75K17kxFiqaQMqkYe0UbaWi37WWI_jXMTQ5b5lts0amqyiARnBmanq4_TXy4vU=e365-pa-nu-w1920', '2025-12-09 02:09:44', 1),
(13, 'เตรียมพบกับงานวิจัยนภาไพศาลสุดเจ๋งทางดาราศาสตร์!', 'งานวิจัยนภาไพศาล\nวันเสาร์ที่ 20 ธันวาคม 2025 ตั้งแต่ 14.00 น. ถึง 17.00 น. ตามเวลาไทย\n\nโปเกมอนเด่น\nภารกิจงานวิจัยภาคสนามธีมอีเวนต์จะมอบรางวัลการเผชิญหน้ากับโปเกมอนเด่น!\n\nลูนาโทน*\nโซลร็อก*\n* คุณจะมีโอกาสเจอตัวสีแตกต่างมากขึ้น!\nงานวิจัยภาคสนาม\nงานวิจัยภาคสนามเฉพาะอีเวนต์ที่มอบการเผชิญหน้ากับลูนาโทน* หรือโซลร็อก* จะพร้อมให้ใช้งานในระหว่างงานวิจัยนภาไพศาล!\n\nโปรดทราบว่างานวิจัยภาคสนามจากเสาโปเกสต็อปจะมีการรีเฟรชโดยเริ่มตั้งแต่เวลา 14.00 น. ตามเวลาไทย\n\n* คุณจะมีโอกาสเจอตัวสีแตกต่างมากขึ้น!\nงานวิจัยแบบจำกัดเวลาแบบเสียเงิน\nภารกิจงานวิจัยภาคสนามธีมอีเวนต์จะมอบรางวัลการเผชิญหน้ากับโปเกมอนเด่น!\n\nลูนาโทน*\nโซลร็อก*\n* โปเกมอนที่ปรากฏตัวระหว่างงานวิจัยแบบจำกัดเวลานี้จะมีโอกาสเท่า ๆ กันในการปรากฏตัวเป็นโปเกมอนสีแตกต่างเช่นเดียวกับโปเกมอนที่สามารถเผชิญหน้าได้ผ่านงานวิจัยภาคสนามในระหว่างอีเวนต์\nโปรดทราบว่างานวิจัยแบบจำกัดเวลามีวันหมดอายุ ภารกิจที่เกี่ยวข้องกับงานวิจัยแบบจำกัดเวลาจะต้องเสร็จสิ้นและต้องรับรางวัลก่อนวันเสาร์ที่ 20 ธันวาคม 2025 เวลา 17.00 น. ตามเวลาไทย\nเทรนเนอร์ทุกคนจะสามารถซื้อและมอบตั๋วเป็นของขวัญให้กับเพื่อน Pokémon GO ที่มีระดับความสนิทสนมเป็นเพื่อนสนิทขึ้นไปอีกด้วย โปรดทราบว่าการซื้อ—รวมถึงการซื้อให้เทรนเนอร์คนอื่น—ไม่สามารถขอคืนเงินได้ (ขึ้นอยู่กับกฎหมายที่บังคับใช้และข้อยกเว้นที่กำหนดไว้ในข้อกำหนดในการให้บริการ) ไม่สามารถใช้โปเกคอยน์ซื้อตั๋วได้\nPokemon GO Web Store – กล่องตั๋วชั้นยอดงานวิจัยนภาไพศาล\nกล่องตั๋วชั้นยอดงานวิจัยนภาไพศาล จะวางจำหน่ายในราคา US$1.99 (หรือราคาเทียบเท่าสกุลเงินท้องถิ่นของคุณ) และประกอบด้วยตั๋วอีเวนต์และลูกอมประหลาด 2 เม็ด!\n\nตรวจสอบได้ใน Pokémon GO Web Store!', 'https://lh3.googleusercontent.com/_bTup9BEq4WVFORrKujTxU_iW5pHtCn_xD754vT0KjdyXS5QOBX1ppwG8VPbHaJWvqwRWi7MFajbvj3nzp3iYOnVL3SrDYZnLIlU=e365-pa-nu-w1920', '2025-12-09 02:10:26', 1),
(14, 'จดบันทึกวันที่ไว้ด้วย: Pokémon GO Fest กลับมาอีกครั้งในปี 2026! เตรียมพบเทศกาลในสถานที่จริงที่โตเกียว ชิคาโก และโคเปนเฮเกน', 'เทรนเนอร์ทุกท่าน\n\nฤดูร้อนหน้า เตรียมพบกับการผจญภัยครั้งยิ่งใหญ่ในชีวิต เมื่อ Pokémon GO Fest กลับมาอีกครั้งในปี 2026! Pokémon GO จะฉลองครบรอบ 10 ปีแห่งชุมชน การค้นพบ และการสำรวจ ติดตามข้อมูลเพิ่มเติมเกี่ยวกับวิธีการร่วมสนุกได้เป็นระยะ!\n\nวิธีสัมผัสประสบการณ์ Pokémon GO Fest ที่ดีที่สุดคือการไปสัมผัสด้วยตัวเอง! เราขอเชิญชวนเทรนเนอร์ทุกท่านมาร่วม 3 อีเวนต์ในสถานที่จริงในเมืองและวันเวลาต่อไปนี้\n\nGO Fest: โตเกียวที่ Bay Area\n\nวันที่อีเวนต์: วันศุกร์ที่ 29 พฤษภาคม – วันจันทร์ที่ 1 มิถุนายน 2026\nการเล่นเกมทั่วทั้งเมืองเวอร์ชันตั๋วจะเริ่มในวันจันทร์ที่ 25 พฤษภาคม 2026\nGO Fest: ชิคาโกที่ Grant Park\n\nวันที่อีเวนต์: วันศุกร์ที่ 5 มิถุนายน – วันอาทิตย์ที่ 7 มิถุนายน 2026\nการเล่นเกมทั่วทั้งเมืองเวอร์ชันตั๋วจะเริ่มในวันพฤหัสที่ 4 มิถุนายน 2026\nGO Fest: โคเปนเฮเกนที่ Fælledparken\n\nวันที่อีเวนต์: วันศุกร์ที่ 12 มิถุนายน – วันอาทิตย์ที่ 14 มิถุนายน 2026\nการเล่นเกมทั่วทั้งเมืองเวอร์ชันตั๋วจะเริ่มในวันพฤหัสที่ 11 มิถุนายน 2026', 'https://lh3.googleusercontent.com/ro0LLVfyOU9lIrtaHxRdzAXxr5h-dECXF0CBJiCkKo0GE1Z6GcE7_2FeC8w8T0y2_FaiaO0ByNR7aH7Y-KZY9uLpAHF9HCloNQ=e365-pa-nu-w1920', '2025-12-12 02:30:38', 1),
(15, 'คอมมิวนิตี้เดย์มกราคม: ซารุโนริ', 'คอมมิวนิตี้เดย์มกราคม 2026: ซารุโนริ\nวันอาทิตย์ที่ 18 มกราคม 2026 ตั้งแต่ 14.00 น. ถึง 17.00 น. ตามเวลาไทย\n\nโปเกมอนลูกลิง ซารุโนริ จะเป็นโปเกมอนเด่นในระหว่างคอมมิวนิตี้เดย์มกราคม!\n\nโปเกมอนเด่น\nซารุโนริจะปรากฏตัวถี่ขึ้นในธรรมชาติ*\n\nหากโชคดี อาจเจอตัวสีแตกต่างหรือตัวที่มาพร้อมกับพื้นหลังพิเศษก็ได้!\nท่าโจมตีเด่น\nวิวัฒนาการบาจินคี (ร่างวิวัฒนาการของซารุโนริ) ระหว่างอีเวนต์หรือภายใน 4 ชั่วโมงหลังจากนั้นเพื่อรับกอริลลันดาซึ่งรู้จักท่าโจมตีชาร์จ “ฮาร์ดแพลนท์”\n\nฮาร์ดแพลนท์\n\nอัปเดตความพร้อมในการใช้ท่าโจมตี\nเริ่มตั้งแต่อีเวนต์เป็นต้นไป กอริลลันดาจะสามารถเรียนรู้ท่าโจมตีชาร์จดรัมแอทแทกได้\n\nดรัมแอทแทก\n\nเทรนเนอร์แบตเทิล: ความแรง 60 และลดพลังโจมตีของโปเกมอนฝ่ายตรงข้ามลง 1 ขั้น\nยิมและการตีบอส: ความแรง 115\nเนื้อเรื่องงานวิจัยพิเศษคอมมิวนิตี้เดย์\nในราคา US$1.99 (หรือราคาเทียบเท่าสกุลเงินท้องถิ่นของคุณ) คุณจะสามารถเข้าถึงงานวิจัยพิเศษเฉพาะคอมมิวนิตี้เดย์ซารุโนริ ทำงานวิจัยนี้ให้เสร็จสิ้นเพื่อรับรางวัลให้มากยิ่งขึ้น รวมถึงสิ่งต่อไปนี้:\n\nการเผชิญหน้า 3 ครั้งกับซารุโนริที่มาพร้อมกับพื้นหลังพิเศษ\nการเผชิญหน้าเพิ่มเติมกับซารุโนริ\nบัตรแบตเทิลพรีเมียม 1 ใบ\nลูกอมประหลาด XL 1 เม็ด\nและของแถมพิเศษอีกมากมาย!\n\nโปรดติดตามข่าวสารว่าตั๋วสำหรับงานวิจัยพิเศษจะออกมาเมื่อไหร่\nอย่าลืม: ตอนนี้คุณสามารถซื้อและมอบตั๋วเป็นของขวัญให้เพื่อนของคุณที่มีระดับมิตรภาพเพื่อนสนิทหรือสูงกว่านั้นได้แล้ว\nหากต้องการมอบตั๋วเป็นของขวัญ ให้แตะที่ตั๋วงานวิจัยพิเศษในร้านค้าในเกม จากนั้นแตะปุ่มของขวัญแทนปุ่มซื้อ\nไม่สามารถแลกคืนตั๋วได้ (ขึ้นอยู่กับกฎหมายที่บังคับใช้และข้อยกเว้นที่กำหนดไว้ในข้อกำหนดในการให้บริการ) โปรดทราบว่างานวิจัยพิเศษนี้จะไม่รวมในเหรียญรางวัลในเกมและจะไม่มีเนื้อเรื่อง\n\nมีข้อจำกัดบางประการ ไม่สามารถมอบของขวัญได้หากผู้รับซื้อตั๋วงานวิจัยพิเศษหรือเคยได้รับของขวัญนี้แล้ว\nโบนัสอีเวนต์\n3× สตาร์ดัสต์จากการจับโปเกมอน\n\n2× ลูกอมจากการจับโปเกมอน\n\nโอกาส 2× สำหรับเทรนเนอร์เลเวล 31 ขึ้นไปที่จะได้รับลูกอม XL จากการจับโปเกมอน\n\nเครื่องหอม (ยกเว้นเครื่องหอมรายวัน) ที่ใช้งานระหว่างอีเวนต์จะอยู่ได้นาน 3 ชั่วโมง\n\nถ่ายสแนปช็อตสักเล็กน้อยระหว่างคอมมิวนิตี้เดย์แล้วจะเจอเซอร์ไพรส์!\n\nอุปกรณ์ปล่อยลัวร์จะอยู่ได้นาน 1 ชั่วโมง และอาจดึงดูดโปเกมอนเด่นได้*\n\nสามารถแลกเปลี่ยนพิเศษได้เพิ่ม 1 ครั้ง สูงสุดถึง 3 ครั้งสำหรับวันนั้น*\n\nการแลกเปลี่ยนจะใช้สตาร์ดัสต์น้อยลง 50%*\n\nแม้ว่าโบนัสส่วนใหญ่จะใช้งานได้เฉพาะในช่วงระยะเวลาอีเวนต์สามชั่วโมงเท่านั้น แต่โบนัสเหล่านี้จะใช้งานได้ตั้งแต่เวลา 14.00 น. ถึง 21.00 น. ตามเวลาไทย\n\nโบนัสอุปกรณ์ปล่อยลัวร์\nตั้งแต่เวลา 14.00 น. ถึง 21.00 น. ตามเวลาไทย มีโอกาสสูงมากที่ซารุโนริจะปรากฏตัวที่เสาโปเกสต็อปที่มีอุปกรณ์ปล่อยลัวร์ทั่วไปเปิดใช้งานอยู่ ซารุโนริที่ถูกดึงดูดด้วยอุปกรณ์ปล่อยลัวร์ทั่วไปจะยังคงมีโอกาสเพิ่มขึ้นที่จะเป็นตัวสีแตกต่างและอาจมาพร้อมกับพื้นหลังพิเศษ นั่นหมายถึงโอกาสเพิ่มขึ้นที่จะได้เผชิญหน้ากับโปเกมอนเด่น แม้หลังจากเวลาอีเวนต์สิ้นสุดลง!\n\nงานวิจัยภาคสนาม\nงานวิจัยภาคสนามในธีมคอมมิวนิตี้เดย์มกราคมจะพร้อมให้ใช้งานแล้ว! จับซารุโนริเพื่อรับรางวัล เช่น สตาร์ดัสต์, ไฮเปอร์บอล, การเผชิญหน้ากับซารุโนริเพิ่มเติม และอีกมากมาย! คุณอาจพบงานวิจัยภาคสนามที่นำไปสู่การเผชิญหน้ากับซารุโนริที่มีพื้นหลังพิเศษ หากโชคดีนะ!', 'https://lh3.googleusercontent.com/dzVdOkon24o8wgF_RBM2eHx5V-PjcK4XyfhggedkdXAQPtDpMQk3_acoodWgyaJbXD2eofvLITgC2gShPu-5wTfnNRp8elk4200=e365-pa-nu-w1920', '2025-12-12 02:31:26', 1),
(16, 'การเฉลิมฉลองจะดำเนินต่อไปในวินเทอร์ฮอลิเดย์ - 2 กับการเปิดตัวของทันด้ง พร้อมด้วยอีเวนต์พิเศษ สุดสัปดาห์ฤดูหนาว!', 'วินเทอร์ฮอลิเดย์ - 2\nวันพุธที่ 24 ธันวาคม เวลา 10.00 น. จนถึงวันจันทร์ที่ 29 ธันวาคม 2025 เวลา 20.00 น. ตามเวลาไทย\n\nโบนัสอีเวนต์\nการจับโปเกมอนธีมอีเวนต์ในธรรมชาติอาจทำให้ได้รับไอเท็มต่าง ๆ เช่น TM ท่าเร็ว, TM ท่าชาร์จ, ผลไพน์สีเงิน, ผลราสสีทอง และลูกอมประหลาด\nโอกาสเพิ่มขึ้นที่จะได้เผชิญหน้ากับโอโดชิชิสีแตกต่างติดกระดิ่งวันหยุดและเดเด็นเนะสีแตกต่างสวมชุดฮอลิเดย์\nนอกจากนี้ บรรลุความสำเร็จขั้นใหญ่บนบัตรผ่าน GO: วินเทอร์ฮอลิเดย์ 2025 เพื่อปลดล็อกโบนัสต่อไปนี้\n\nTier 1\n\n2× XP จากการส่งของขวัญ\nบัตรผ่าน GO Deluxe: 2× สตาร์ดัสต์จากการเปิดของขวัญ\nTier 2\n\nอาจได้รับไอเท็มเป็นรางวัลเพิ่มเติมจากการเปิดของขวัญ\nบัตรผ่าน GO Deluxe: ระยะทางฟักไข่ 1/2 เมื่อไข่ถูกวางไว้ในเครื่องฟักไข่ระหว่างช่วงเวลาอีเวนต์\nTier 3\n\nXP เพิ่มอีก 50% สำหรับการชนะแบตเทิลตีบอส\nบัตรผ่าน GO Deluxe: 2× XP จากการจับโปเกมอน\nโปเกมอนเปิดตัวใหม่\nโปเกมอนต่อไปนี้ที่ค้นพบครั้งแรกในภูมิภาคกาลาร์จะเปิดตัวใน Pokémon GO แล้ว!\n\nทันด้ง\nโทร็อกกอน\nเซคิทันซัง\n\nคุณสามารถใช้ลูกอมทันด้ง 25 เม็ดวิวัฒนาการทันด้งเป็นโทร็อกกอนและใช้ลูกอมทันด้ง 100 เม็ดวิวัฒนาการโทร็อกกอนเป็นเซคิทันซัง\nเผชิญหน้าในธรรมชาติ\nคุณอาจได้เผชิญหน้ากับโปเกมอนธีมอีเวนต์ในธรรมชาติ รวมถึง ดารุมักกะ (ร่างกาลาร์), คาจิคอล, อารุคุจิระ* และโปเกมอนอื่น ๆ อีกมากมาย! และอาจได้เผชิญหน้ากับเดเด็นเนะสวมชุดฮอลิเดย์* หรือทันด้งด้วย!\n\n*หากโชคดี อาจเจอตัวสีแตกต่างก็ได้!\nไข่\nโปเกมอนต่อไปนี้จะฟักออกจากไข่ 7 กม.\n\nพิชูสวมหมวกซานต้า*\nมุจูล*\nคูมะชุนติดโบ*\nฟรีจิโอ*\nยูกิฮามิ\n\n* หากโชคดี อาจเจอตัวสีแตกต่างก็ได้!\nตีบอส\nโปเกมอนต่อไปนี้จะปรากฏตัวในการตีบอส\n\nตีบอสหนึ่งดาว\nแซนด์ (ร่างอโลลา)*\nดารุมักกะ (ร่างกาลาร์)*\nทันด้ง\n\nตีบอสสามดาว\nบาร์เรียด (ร่างกาลาร์)*\nอุซกกีสวมชุดฮอลิเดย์*\nเด็นจิมูชิสวมชุดฮอลิเดย์*\n\n*หากโชคดี อาจเจอตัวสีแตกต่างก็ได้!\nการเผชิญหน้างานวิจัยภาคสนาม\nภารกิจงานวิจัยภาคสนามธีมอีเวนต์จะพร้อมให้ใช้งาน\n\nทำภารกิจงานวิจัยภาคสนามให้เสร็จสิ้นเพื่อรับสตาร์ดัสต์และการเผชิญหน้ากับโปเกมอนธีมอีเวนต์\n\nสุดสัปดาห์ฤดูหนาว\nวันเสาร์ที่ 27 ธันวาคม เวลา 10.00 น. จนถึงวันอาทิตย์ที่ 28 ธันวาคม 2025 เวลา 20.00 น. ตามเวลาไทย\n\nโบนัสอีเวนต์\nไม่มีการจำกัดจำนวนแต้ม GO ที่คุณสามารถรับได้ต่อวัน!\nเควสต์โบนัสรายวันสำหรับบัตรผ่าน GO: วินเทอร์ฮอลิเดย์ 2025\nโอกาสเพิ่มขึ้นที่จะได้เผชิญหน้ากับอีวุยสีแตกต่างสวมหมวกวันหยุดจากภารกิจงานวิจัยแบบจำกัดเวลา\nงานวิจัยแบบจำกัดเวลา\nจะมีโอกาสทำงานวิจัยแบบจำกัดเวลาฟรี\n\nรางวัลงานวิจัยแบบจำกัดเวลารวมถึงสิ่งต่อไปนี้\n\nXP\nสตาร์ดัสต์\nการเผชิญหน้ากับอีวุยสวมหมวกวันหยุด*\nโปรดทราบว่างานวิจัยแบบจำกัดเวลามีวันหมดอายุ ภารกิจที่เกี่ยวข้องกับงานวิจัยแบบจำกัดเวลานี้จะต้องเสร็จสิ้นและต้องรับรางวัลก่อนวันอาทิตย์ที่ 28 ธันวาคม 2025 เวลา 20.00 น. ตามเวลาไทย', 'https://lh3.googleusercontent.com/IbB54nXimLLbwTHvJy1wmiQ8mBYDz5xqdGrJQeJzKorncqZaAegI4SSCnb20Qv4Zds4HvrEE1RYlNB3OYaqS_r649cKNmQFBZmY=e365-pa-nu-w1920', '2025-12-12 02:31:51', 1),
(17, 'คอมมิวนิตี้เดย์ (รีเทิร์น) มกราคม 2026: โพจจามะ', 'วันอาทิตย์ที่ 4 มกราคม 2026 ตั้งแต่ 14.00 น. ถึง 17.00 น. ตามเวลาไทย\n\nโปเกมอนเพนกวิน โพจจามะจะเป็นโปเกมอนเด่นในระหว่างคอมมิวนิตี้เดย์ (รีเทิร์น) มกราคม!\n\nโปเกมอนเด่น\nโพจจามะจะปรากฏตัวถี่ขึ้นในธรรมชาติ*\n\n* หากโชคดี อาจเจอตัวสีแตกต่างหรือตัวที่มาพร้อมกับพื้นหลังพิเศษก็ได้!\nท่าโจมตีเด่น\nวิวัฒนาการโพจไทชิ (ร่างวิวัฒนาการของโพจจามะ) ตั้งแต่เริ่มต้นอีเวนต์จนถึงวันที่ 4 มกราคม 2026 เวลา 21.00 น. ตามเวลาไทย เพื่อรับเอ็มเพลท์ซึ่งรู้ท่าโจมตีชาร์จ “ไฮโดรแคนนอน”\n\nไฮโดรแคนนอน\n\nเทรนเนอร์แบตเทิล: ความแรง 80\nยิมและการตีบอส: ความแรง 90\nเนื้อเรื่องงานวิจัยพิเศษคอมมิวนิตี้เดย์\nในราคา US$1.99 (หรือราคาเทียบเท่าสกุลเงินท้องถิ่นของคุณ) คุณจะสามารถเข้าถึงงานวิจัยพิเศษเฉพาะคอมมิวนิตี้เดย์โพจจามะ ทำงานวิจัยนี้ให้เสร็จสิ้นเพื่อรับรางวัลให้มากยิ่งขึ้น รวมถึงสิ่งต่อไปนี้:\n\nการเผชิญหน้า 3 ครั้งกับโพจจามะที่มาพร้อมกับพื้นหลังพิเศษ\nการเผชิญหน้าเพิ่มเติมกับโพจจามะ\nบัตรแบตเทิลพรีเมียม 1 ใบ\nลูกอมประหลาด XL 1 เม็ด\nและของแถมพิเศษอีกมากมาย!\n\nโปรดติดตามข่าวสารว่าตั๋วสำหรับงานวิจัยพิเศษจะออกมาเมื่อไหร่\nอย่าลืม: ตอนนี้คุณสามารถซื้อและมอบตั๋วเป็นของขวัญให้เพื่อนของคุณที่มีระดับมิตรภาพเพื่อนสนิทหรือสูงกว่านั้นได้แล้ว*\nหากต้องการมอบตั๋วเป็นของขวัญ ให้แตะที่ตั๋วงานวิจัยพิเศษในร้านค้าในเกม จากนั้นแตะปุ่มของขวัญแทนปุ่มซื้อ**\n*ไม่สามารถแลกคืนตั๋วได้ (เป็นไปตามกฎหมายที่มีผลและข้อยกเว้นที่กำหนดไว้ล่วงหน้าในเงื่อนไขการให้บริการ) โปรดทราบว่างานวิจัยพิเศษนี้จะไม่รวมในเหรียญรางวัลในเกมและจะไม่มีเนื้อเรื่อง\n**มีข้อจำกัดบางประการ ไม่สามารถมอบของขวัญได้หากผู้รับซื้อตั๋วงานวิจัยพิเศษหรือเคยได้รับของขวัญนี้แล้ว\nโบนัสอีเวนต์\nระยะทางฟักไข่ 1/4 เมื่อไข่ถูกวางเข้าไปในเครื่องฟักไข่ระหว่างอีเวนต์\nเครื่องหอม (ยกเว้นเครื่องหอมรายวัน) ที่ใช้งานระหว่างอีเวนต์จะอยู่ได้นาน 3 ชั่วโมง\nถ่ายสแนปช็อตสักเล็กน้อยระหว่างคอมมิวนิตี้เดย์แล้วจะเจอเซอร์ไพรส์!\nอุปกรณ์ปล่อยลัวร์จะอยู่ได้นาน 1 ชั่วโมงและอาจดึงดูดโปเกมอนเด่น\n* แม้ว่าโบนัสส่วนใหญ่จะใช้งานได้ในระหว่างอีเวนต์ 3 ชั่วโมง แต่โบนัสเหล่านี้จะใช้งานได้ตั้งแต่ 14.00 น. ถึง 21.00 น. ตามเวลาไทยเท่านั้น\nโบนัสอุปกรณ์ปล่อยลัวร์\nในวันที่ 4 มกราคม 2026 ตั้งแต่เวลา 14.00 น. ถึง 21.00 น. ตามเวลาไทย มีโอกาสสูงมากที่โพจจามะจะปรากฏตัวที่เสาโปเกสต็อปที่มีอุปกรณ์ปล่อยลัวร์มาตรฐานเปิดใช้งานอยู่ โพจจามะที่ถูกดึงดูดด้วยอุปกรณ์ปล่อยลัวร์มาตรฐานจะยังคงมีโอกาสเพิ่มขึ้นที่จะเป็นตัวสีแตกต่างและอาจมาพร้อมกับพื้นหลังพิเศษ นั่นหมายถึงโอกาสเพิ่มขึ้นที่จะได้เผชิญหน้ากับโปเกมอนเด่น แม้หลังจากเวลาอีเวนต์สิ้นสุดลง!\n\nงานวิจัยภาคสนาม\nงานวิจัยภาคสนามในธีมคอมมิวนิตี้เดย์ (รีเทิร์น) มกราคมจะพร้อมให้ใช้งานแล้ว! จับโพจจามะเพื่อรับรางวัล เช่น สตาร์ดัสต์, ซูเปอร์บอล, การเผชิญหน้ากับโพจจามะเพิ่มเติม และอีกมากมาย! คุณอาจพบงานวิจัยภาคสนามที่นำไปสู่การเผชิญหน้ากับโพจจามะที่มีพื้นหลังพิเศษ หากโชคดีนะ!\n\nPokemon GO Web Store – กล่องตั๋วไฮเปอร์คอมมิวนิตี้เดย์\nกล่องไฮเปอร์คอมมิวนิตี้เดย์ จะวางจำหน่ายในราคา US$1.99 (หรือราคาเทียบเท่าสกุลเงินท้องถิ่นของคุณ) และประกอบด้วยตั๋วอีเวนต์และไฮเปอร์บอล 5 ลูก!\n\nข้อเสนอ Web Store นี้จะวางจำหน่ายตั้งแต่วันที่ 1 มกราคม 2026 เวลา 10.00 น. ตามเวลาไทย\n\nตรวจสอบได้ใน Pokémon GO Web Store!\n\nกำลังหาเพื่อนเทรนเนอร์มาเข้าร่วมหรือเปล่า?\nหากคุณกำลังหาเทรนเนอร์อื่นในพื้นที่ของคุณเพื่อแลกเปลี่ยน, แบตเทิล หรือเข้าร่วมตีบอสในคอมมิวนิตี้เดย์ ลองไปดูแผนที่วันคอมมิวนิตี้เดย์ของเราสิ! คุณจะพบกับอีเวนต์ผู้นำชุมชนและสวนสาธารณะชุมชนที่นี่\n\nผู้นำชุมชนคือคนที่จัดอีเวนต์ Pokémon GO สำหรับชุมชนของตน ซึ่งได้รับการสนับสนุนจาก Niantic หากไม่มีผู้นำคอมมิวนิตี้ใกล้ ๆ คุณ คุณสามารถค้นหา Campfire ได้โดยดาวน์โหลดแอป และค้นหาการพบปะในพื้นที่อื่น ๆ ในละแวกใกล้เคียง\n\nสวนสาธารณะชุมชนคือพื้นที่ในเมืองของคุณที่เคยเป็นสถานที่ยอดนิยมในอดีตสำหรับคอมมิวนิตี้เดย์ สวนสาธารณะเหล่านี้อาจเป็นสถานที่เล่นที่สนุกที่จะเล่นกับชุมชนในพื้นที่ของคุณในขณะที่เพลิดเพลินไปกับอากาศบริสุทธิ์* เราหวังว่าแผนที่นี้จะช่วยให้เทรนเนอร์ได้เชื่อมต่อกัน!\n\nเราแจ้งสถานที่ยอดนิยมเพื่อเป็นข้อมูลเท่านั้น: Niantic ไม่ได้จัดหรือดำเนินอีเวนต์ทางการหรือไม่เป็นทางการในสถานที่เหล่านี้ โปรดระวังสภาพแวดล้อมรอบ ๆ ของคุณในขณะที่เล่นเกมของ Niantic\n\nกิจกรรมของผู้แทนคอมมิวนิตี้\nกิจกรรมของผู้นำคอมมิวนิตี้\nสวนสาธารณะยอดนิยม\nเช็คอินเข้าร่วมอีเวนต์ผู้นำชุมชนเพื่อรับงานวิจัยแบบจำกัดเวลาที่จะนำไปสู่การเผชิญหน้าเพิ่มเติมกับโพจจามะที่มาพร้อมกับพื้นหลังพิเศษ เช่นเดียวกับรางวัลไอเท็มพรีเมียมอื่น ๆ!', 'https://lh3.googleusercontent.com/xFKPZa9hcKpzYwlH_LkWMvl2G1L1oQV4GbkATRA52w0Nyrn3PIjyURpE9lj9KqGoJukjWvox7VmxMxn8Ufz4u-L-VE0GxVdvxA=e365-pa-nu-w1920', '2025-12-12 02:32:23', 1),
(20, 'ต้อนรับปี 2026 กับอีเวนต์ปีใหม่ใน Pokémon GO!', 'ปีใหม่ 2026\nวันพุธที่ 31 ธันวาคม 2025 เวลา 10.00 น. ถึงวันอาทิตย์ที่ 4 มกราคม 2026 เวลา 20.00 น. ตามเวลาไทย\n\nโบนัสอีเวนต์\n2× XP จากตีบอส\n2× สตาร์ดัสต์จากการตีบอส\nโอกาสเพิ่มขึ้นที่จะได้เผชิญหน้ากับพิคาชูสีแตกต่างสวมหมวกปาร์ตี้ทรงสูงในธรรมชาติและในการตีบอส\nสำรวจพร้อมการตกแต่ง\nในระหว่างอีเวนต์นี้ ดอกไม้ไฟฉลองเทศกาลจะสว่างขึ้นบนท้องฟ้า เราหวังว่าคุณจะสนุกกับการตกแต่งสีสันสวยงามนี้!\n\nเผชิญหน้าในธรรมชาติ\nอาจได้เผชิญหน้ากับโปเกมอนธีมอีเวนต์ในธรรมชาติ รวมถึง ฟุชิกิดาเนะสวมหมวกปาร์ตี้*, พูรินติดโบ*, โฮโฮสวมชุดปีใหม่* และโปเกมอนอื่น ๆ อีกมากมาย! และอาจได้เผชิญหน้ากับพิคาชูสวมหมวกปาร์ตี้ทรงสูงด้วย*!\n\n*หากโชคดี อาจเจอตัวสีแตกต่างก็ได้!\nตีบอส\nโปเกมอนต่อไปนี้จะปรากฏตัวในการตีบอส\n\nตีบอสหนึ่งดาว\nพิคาชูสวมหมวกปาร์ตี้ทรงสูง*\nเคมุตโสะสวมหมวกปาร์ตี้*\n\nตีบอสสามดาว\nรัตตาสวมหมวกปาร์ตี้*\nนิโดริโนสวมหมวกปาร์ตี้*\nเก็งกาสวมหมวกปาร์ตี้*\nโซนานส์สวมหมวกปาร์ตี้*\n\n*หากโชคดี อาจเจอตัวสีแตกต่างก็ได้!\nการเผชิญหน้างานวิจัยภาคสนาม\nภารกิจงานวิจัยภาคสนามธีมอีเวนต์จะพร้อมให้ใช้งาน\n\nทำภารกิจงานวิจัยภาคสนามให้เสร็จสิ้นเพื่อรับสตาร์ดัสต์\n\nงานวิจัยภาคสนามรายวัน\nในระหว่างอีเวนต์ เทรนเนอร์ทุกท่านจะได้รับโบนัสภารกิจงานวิจัยภาคสนามประจำวันในแต่ละวันที่ล็อกอิน ซึ่งจะมอบรางวัลเป็นไข่แห่งความสุขหนึ่งฟองหรือเครื่องหอม 1 เครื่อง*\n\n* หากต้องการรับภารกิจงานวิจัยภาคสนามโบนัส คุณต้องมีภารกิจงานวิจัยภาคสนามที่ทำงานอยู่ไม่เกิน 3 ภารกิจ เมื่อคุณล็อกอินเป็นครั้งแรกในแต่ละวัน\nการแลกเปลี่ยนนำโชค!\nจำนวนโปเกมอนนำโชคที่รับประกันว่าเทรนเนอร์จะได้รับจากการแลกเปลี่ยนเพิ่มขึ้นจาก 35 ตัวเป็น 45 ตัว! และเริ่มตั้งแต่อีเวนต์นี้เป็นต้นไป หากคุณแลกเปลี่ยนโปเกมอนที่อยู่ในที่จัดเก็บโปเกมอนของคุณตั้งแต่ปี 2020 คุณจะได้รับประกันว่ามันจะกลายเป็นโปเกมอนนำโชคจนกว่าจะถึงขีดจำกัด! การเปลี่ยนแปลงนี้มีผลถาวร\n\nงานวิจัยแบบจำกัดเวลาแบบเสียเงิน\nในราคา US$1.99 (หรือราคาเทียบเท่าสกุลเงินท้องถิ่นของคุณ) คุณจะสามารถเข้าถึงงานวิจัยแบบจำกัดเวลาเฉพาะอีเวนต์ การซื้อตั๋วใบนี้จะทำให้ได้รับโบนัสดังต่อไปนี้ในอีเวนต์ปีใหม่ 2026\n\nบัตรตีบอสเพิ่มเติม 1 ใบต่อวันจากการหมุนแผ่นภาพที่ยิม (รวมเป็น 2 ใบต่อวัน)\nรางวัลงานวิจัยแบบจำกัดเวลามีดังต่อไปนี้\n\nบัตรแบตเทิลพรีเมียม 2 ใบ\n3,000 สตาร์ดัสต์\nการเผชิญหน้ากับพิคาชูสวมหมวกปาร์ตี้ทรงสูง\nเทรนเนอร์ทุกคนจะสามารถซื้อและมอบตั๋วเป็นของขวัญให้กับเพื่อน Pokémon GO ที่มีระดับความสนิทสนมเป็นเพื่อนสนิทขึ้นไปอีกด้วย โปรดทราบว่าการซื้อ—รวมถึงการซื้อให้เทรนเนอร์คนอื่น—ไม่สามารถขอคืนเงินได้ (ขึ้นอยู่กับกฎหมายที่บังคับใช้และข้อยกเว้นที่กำหนดไว้ในข้อกำหนดในการให้บริการ) ไม่สามารถใช้โปเกคอยน์ซื้อตั๋วได้\n\nโปรดทราบว่างานวิจัยแบบจำกัดเวลามีวันหมดอายุ ภารกิจที่เกี่ยวข้องกับงานวิจัยแบบจำกัดเวลานี้จะต้องเสร็จสิ้นและต้องรับรางวัลก่อนวันอาทิตย์ที่ 4 มกราคม 2026 เวลา 20.00 น. ตามเวลาไทย', 'https://lh3.googleusercontent.com/JvFmn36fH62yDIhVqUAfO8L7S_lco6KJ_q629XaWv1P9immIqBfWGrcXDpc8ffbj1WAC26U-i47z9NtaIzCA2oigE05H7okNjao=e365-pa-nu-w1920', '2025-12-17 01:54:33', 1),
(21, 'ต่อสู้กับฮีโร่ฝาแฝดเพื่อความจริงหรืออุดมคติในระหว่างวันตีบอสรวมร่างคิวเรม!', 'วันตีบอสรวมร่างคิวเรม\nวันเสาร์ที่ 10 มกราคม 2026 ตั้งแต่ 14.00 น. ถึง 17.00 น. ตามเวลาไทย\n\nโบนัสอีเวนต์\nเรชิรัม, เซครอม, แบล็กคิวเรม* และไวท์คิวเรม* จะปรากฏตัวถี่ขึ้นในการตีบอส และบอสเหล่านี้จะสลับกันทุกครึ่งชั่วโมงในระหว่างช่วงเวลาอีเวนต์ เรชิรัมและแบล็กคิวเรมจะปรากฏตัวในการตีบอสก่อน ตามด้วยเซครอมและไวท์คิวเรม รับมือการตีบอสเหล่านี้เพื่อรับพลังงานรวมร่างที่สามารถนำมาใช้รวมร่างคิวเรมให้เป็นร่างที่น่าเกรงขามยิ่งขึ้น!\n\nรับบัตรตีบอสเพิ่มฟรีสูงสุดถึง 5 ใบจากการหมุนแผ่นภาพยิม (รวมเป็น 6 ใบ)\n\nโอกาสเพิ่มขึ้นที่จะเผชิญหน้ากับเรชิรัมสีแตกต่าง, เซครอมสีแตกต่าง และคิวเรมสีแตกต่างในการตีบอส\n\nขีดจำกัดบัตรตีบอสระยะไกลจะเพิ่มขึ้นเป็น 20 ครั้งตั้งแต่วันศุกร์ที่ 9 มกราคม เวลา 17.00 น. ถึงวันเสาร์ที่ 10 มกราคม 2026 เวลา 20.00 น. ตามเวลามาตรฐานแปซิฟิค\n\nเทรนเนอร์ทุกท่านจะมีโอกาสจับคิวเรมได้หลังจากเอาชนะแบล็กคิวเรมหรือไวท์คิวเรม\n\nท่าโจมตีเด่น\nเรชิรัมที่เผชิญหน้าในการตีบอสจะรู้จักท่าโจมตีชาร์จ “ครอสเฟลม”ด้วย\nเซครอมที่เผชิญหน้าในการตีบอสจะรู้จักท่าโจมตีชาร์จ “ครอสธันเดอร์”ด้วย\nคิวเรมที่เผชิญหน้าในการตีบอสอาจรู้จักท่าโจมตีชาร์จ “โลกเยือกแข็ง”\nตั๋วอีเวนต์\nในราคา US$4.99 (หรือราคาเทียบเท่าสกุลเงินท้องถิ่นของคุณ) คุณสามารถซื้อตั๋วที่มอบโบนัสต่อไปนี้ได้\n\nบัตรตีบอสเพิ่มเติม 8 ใบจากการหมุนแผ่นภาพยิม (รวมเป็น 14 ใบต่อวัน)\nโอกาสในการได้รับลูกอมประหลาด XL จากตีบอสเพิ่มขึ้น\nXP เพิ่มอีก 50% จากตีบอส\n2× สตาร์ดัสต์จากตีบอส\nโบนัสเหล่านี้จะมีผลในวันเสาร์ที่ 10 มกราคม 2026 ตั้งแต่เวลา 14.00 น. ถึง 17.00 น. ตามเวลาไทย\n\nเทรนเนอร์ทุกคนจะสามารถซื้อและมอบตั๋วเป็นของขวัญให้กับเพื่อน Pokémon GO ที่มีระดับมิตรภาพเป็นเพื่อนสนิทขึ้นไปอีกด้วย โปรดทราบว่าการซื้อ—รวมถึงการซื้อให้เทรนเนอร์คนอื่น—ไม่สามารถขอคืนเงินได้ (ขึ้นอยู่กับกฎหมายที่บังคับใช้และข้อยกเว้นที่กำหนดไว้ในข้อกำหนดในการให้บริการ) ไม่สามารถใช้โปเกคอยน์ซื้อตั๋วได้\n\nโปรดทราบว่าตั๋วใบนี้จะวางจำหน่ายในร้านค้าในเกมเท่านั้นจนถึงวันเสาร์ที่ 10 มกราคม 2026 เวลา 17.00 น. ตามเวลาไทย\nPokemon GO Web Store – กล่องตั๋วชั้นยอดวันตีบอสรวมร่างคิวเรม\nกล่องตั๋วชั้นยอดวันตีบอสรวมร่างคิวเรม จะวางจำหน่ายในราคา US$4.99 (หรือราคาเทียบเท่าสกุลเงินท้องถิ่นของคุณ) และประกอบด้วยตั๋วอีเวนต์และโบนัสบัตรแบตเทิลพรีเมียม!\n\nการรวมร่างโปเกมอน\nการรวมร่างโปเกมอนคือความสามารถในการรวมโปเกมอนบางตัวให้กลายเป็นร่างเดียวที่ทรงพลังยิ่งขึ้นโดยมีรูปลักษณ์ที่เปลี่ยนไป\n\nแบล็กคิวเรมและไวท์คิวเรม\nหากมีพลังงานรวมร่างเพียงพอ ก็สามารถรวมร่างคิวเรมกับเซครอมให้กลายเป็นแบล็กคิวเรมหรือรวมร่างกับเรชิรัมให้กลายเป็นไวท์คิวเรมได้\n\nเทรนเนอร์ทุกท่านสามารถรวมร่างคิวเรมและเซครอมได้โดยใช้พลังงานรวมร่างโวลต์ 1,000 หน่วย, ลูกอมคิวเรม 30 เม็ด และลูกอมเซครอม 30 เม็ด\nเทรนเนอร์สามารถรวมร่างคิวเรมและเรชิรัมได้โดยใช้พลังงานรวมร่างเบลซ 1,000 หน่วย, ลูกอมคิวเรม 30 เม็ด และลูกอมเรชิรัม 30 เม็ด\nคิวเรมที่ถูกรวมร่างแล้วจะยังคงอยู่ในร่างนี้จนกว่าเทรนเนอร์จะแยกพวกมันออกจากกัน การแยกร่างจะไม่เสียค่าพลังงานรวมร่างหรือลูกอมโปเกมอน\n\nแบล็กคิวเรมและไวท์คิวเรมไม่สามารถแลกเปลี่ยน, ถ่ายโอนไปยังศาสตราจารย์ หรือย้ายไปยัง Pokémon HOME ได้\n\nพลังงานรวมร่างโวลต์และพลังงานรวมร่างเบลซ\nพลังงานรวมร่างโวลต์และพลังงานรวมร่างเบลซเป็นแหล่งพลังงานที่หายากมาก ซึ่งสามารถใช้เพื่อรวมร่างคิวเรมให้กลายเป็นร่างที่น่าเกรงขามยิ่งขึ้น\n\nเทรนเนอร์ทุกท่านสามารถรับพลังงานรวมร่างโวลต์หรือพลังงานรวมร่างเบลซจากการเอาชนะแบล็กคิวเรมหรือไวท์คิวเรมในตีบอส\n\nเอฟเฟกต์ผจญภัย: ฟรีซโวลต์\nหลังจากรวมร่างเซครอมกับคิวเรมที่รู้จักท่าโจมตีชาร์จ “โลกเยือกแข็ง” แล้ว “โลกเยือกแข็ง” จะกลายเป็นท่าโจมตีชาร์จ “ฟรีซโวลต์” “ฟรีซโวลต์” จะเปลี่ยนกลับเป็น “โลกเยือกแข็ง” เมื่อเซครอมแยกร่างออกจากคิวเรม*\n\nเทรนเนอร์ทุกท่านสามารถใช้ 5,000 สตาร์ดัสต์และลูกอมคิวเรม 5 เม็ดเพื่อเปิดใช้งานเอฟเฟกต์ผจญภัยของ “ฟรีซโวลต์” ซึ่งจะปล่อยน้ำแข็งที่มีประจุไฟฟ้าเป็นเวลา 10 นาที ในระหว่างเวลานี้ โปเกมอนที่เผชิญหน้าจะไม่สามารถเคลื่อนไหวได้ ทำให้จับได้ง่ายขึ้น รวมถึงการใช้อุปกรณ์เสริมเชื่อมต่อด้วย\n\nคุณสามารถขยายเวลาเอฟเฟกต์ผจญภัยของ “ฟรีซโวลต์” ได้ครั้งละ 10 นาทีโดยใช้สตาร์ดัสต์และลูกอมคิวเรมเพิ่ม สามารถขยายเวลาได้สูงสุดถึง 2 ชั่วโมงในแต่ละครั้งที่คุณแตะใช้ และคุณสามารถแตะใช้อีกครั้งเพื่อเพิ่มเวลา—รวมสูงสุดถึง 24 ชั่วโมง!\n\nไม่สามารถใช้งาน “ฟรีซโวลต์” พร้อมกับเอฟเฟกต์ผจญภัยอื่น ๆ\n\nในเวลานี้ แบล็กคิวเรมจะไม่สามารถเรียนรู้ “ฟรีซโวลต์” ผ่าน TM ท่าชาร์จหรือ TM ท่าชาร์จชั้นเลิศได้\nเอฟเฟกต์ผจญภัย: โคลด์แฟลร์\nหลังจากรวมร่างเรชิรัมกับคิวเรมที่รู้จักท่าโจมตีชาร์จ “โลกเยือกแข็ง” แล้ว “โลกเยือกแข็ง” จะกลายเป็นท่าโจมตีชาร์จ “โคลด์แฟลร์” “โคลด์แฟลร์” จะเปลี่ยนกลับเป็น “โลกเยือกแข็ง” เมื่อเรชิรัมแยกร่างออกจากคิวเรม*\n\nเทรนเนอร์ทุกท่านสามารถใช้ 5,000 สตาร์ดัสต์และลูกอมคิวเรม 5 เม็ดเพื่อเปิดใช้งานเอฟเฟกต์ผจญภัยของ “โคลด์แฟลร์” ซึ่งจะเปิดใช้งานพลังงานเยือกแข็งเป็นเวลา 10 นาที ในระหว่างเวลานี้ วงแหวนเป้าหมายในการเผชิญหน้ากับโปเกมอนจะเคลื่อนที่ช้าลง การขว้างได้สุดยอดจึงทำได้ง่ายขึ้น และการจับโปเกมอนก็ง่ายขึ้นมากด้วย รวมถึงการใช้อุปกรณ์เสริมเชื่อมต่อด้วย\n\nคุณสามารถขยายเวลาเอฟเฟกต์ผจญภัยของ “โคลด์แฟลร์” ได้ครั้งละ 10 นาทีโดยใช้สตาร์ดัสต์และลูกอมคิวเรมเพิ่ม สามารถขยายเวลาได้สูงสุดถึง 2 ชั่วโมงในแต่ละครั้งที่คุณแตะใช้ และคุณสามารถแตะใช้อีกครั้งเพื่อเพิ่มเวลา—รวมสูงสุดถึง 24 ชั่วโมง!\n\nไม่สามารถใช้งาน “โคลด์แฟลร์” พร้อมกับเอฟเฟกต์ผจญภัยอื่น ๆ\n\nในเวลานี้ ไวท์คิวเรมจะไม่สามารถเรียนรู้ “โคลด์แฟลร์” ผ่าน TM ท่าชาร์จหรือ TM ท่าชาร์จชั้นเลิศได้', 'https://lh3.googleusercontent.com/CeXPlMxdc5YhFVVxshsOUaJ5P0xx53Sr6h-urfhuDAEX5F4Zi1nFas_u3kjf_0o8qK1yGU0Cp1fTXfpLEuvrxY8_NYH7GhUqH8Q=e365-pa-nu-w1920', '2025-12-17 01:58:13', 1),
(22, 'Pokémon GO is coming to IIT-Bombay for Techfest 2025!', 'ผู้ฝึกสอน\n\nPokémon GO จะมาปรากฏตัวที่ IIT-Bombay ในงาน Techfest 2025 ระหว่างวันที่ 22-24 ธันวาคม 2025 เหล่าเทรนเนอร์จะได้พบกับโบนัสในเกมสุดเร้าใจ และบูธ Pokémon GO อย่างเป็นทางการภายในวิทยาเขต IIT-Bombay ในมุมไบ นอกจากนี้ เทรนเนอร์ที่อยู่ใกล้เคียงยังสามารถเข้าร่วมการแข่งขัน Catch Cup ได้อีกด้วย!\n\nPokémon GO ในงาน Techfest 2025\nวันจันทร์ที่ 22 ธันวาคม เวลา 10:00 น. ถึงวันพุธที่ 24 ธันวาคม พ.ศ. 2568 เวลา 20:00 น. ตามเวลาท้องถิ่น\n\nการเผชิญหน้าในป่า\nเทรนเนอร์อาจได้พบกับบูลบาซอร์*, ชาร์แมนเดอร์*, สควอร์ตเติล*, ปิกาชู* และอีวี* นอกจากนี้ คุณอาจได้พบกับลาพราส* และสนอร์แล็กซ์* ด้วย!\n\n*ถ้าโชคดี คุณอาจเจอตัวสีพิเศษก็ได้!\n\nโบนัสกิจกรรม\n• โมดูลล่อโปเกมอนจะใช้งานได้นานสามชั่วโมง\n• รับลูกอมเพิ่มจากการแลกเปลี่ยน\n• วิวัฒนาการ Ivysaur (วิวัฒนาการของ Bulbasaur) เพื่อให้ได้ Venusaur ที่รู้ท่า Frenzy Plant\n• วิวัฒนาการ Charmeleon (วิวัฒนาการของ Charmander) เพื่อให้ได้ Charizard ที่รู้ท่า Blast Burn\n• วิวัฒนาการ Wartortle (วิวัฒนาการของ Squirtle) เพื่อให้ได้ Blastoise ที่รู้ท่า Hydro Cannon\n\nการวิจัยแบบกำหนดเวลา\nจะมีโอกาสให้ทำวิจัยแบบจำกัดเวลาได้ฟรี\n\nรางวัลจากการทำภารกิจวิจัยแบบจำกัดเวลา ได้แก่ สิ่งของต่อไปนี้\n\n• ค่าประสบการณ์ (XP)\n• สตาร์ดัสต์\n• โมดูลล่อโปเกมอน\n• การเผชิญหน้ากับโปเกมอนตามธีมกิจกรรม\n• และอื่นๆ อีกมากมาย!\n\nโปรดทราบว่าภารกิจวิจัยแบบจำกัดเวลาจะหมดอายุลง ภารกิจที่เกี่ยวข้องกับภารกิจวิจัยแบบจำกัดเวลานี้จะต้องทำเสร็จและรับรางวัลก่อนวันพุธที่ 31 ธันวาคม 2025 เวลา 20:00 น. ตามเวลาท้องถิ่น', 'https://lh3.googleusercontent.com/96uTH3bDdZOftuKQPlpJXhgdgGA8lElCzdWjYZNnUzz8yfvFxJB_4rAKDLy4_yHqbKQEb9t3Xi98ecIsplrGChgZ6auj0u_bt7JkiYSPIhvk1GE=w1440-e365', '2025-12-22 07:03:47', 1),
(23, 'ระวังตัวให้ดีและเตรียมรับมือกับ Klawf และอีกมากมายในงาน Pinch Perfect!', 'หยิกให้สมบูรณ์แบบ\nวันอังคารที่ 6 มกราคม เวลา 10:00 น. ถึงวันอาทิตย์ที่ 11 มกราคม พ.ศ. 2569 เวลา 20:00 น. ตามเวลาท้องถิ่น\n\nโปเกมอนเปิดตัวครั้งแรก\nKlawf โปเกมอนจอมซุ่มโจมตี จะปรากฏตัวครั้งแรกใน Pokémon GO!\n\nนอกจากนี้ เป็นครั้งแรกในเกม Pokémon GO ที่คุณจะสามารถพบกับ Dhelmise สีเงาได้ หากคุณโชคดี!\n\nโบนัสกิจกรรม\nได้รับ XP 2 เท่าเมื่อจับโปเกมอน\n\nมีโอกาสมากขึ้นที่จะพบโปเกมอน Corphish สีเงา, Dwebble สีเงา และ Clauncher สีเงา\n\nการเผชิญหน้าในป่า\nคุณอาจพบโปเกมอนธีมกิจกรรมในป่า รวมถึง Corphish*, Dwebble*, Clauncher* และอีกมากมาย คุณอาจพบ Tirtouga* และ Archen* ด้วย!\n\n*ถ้าโชคดี คุณอาจเจอตัวสีพิเศษก็ได้*\nการบุกค้น\nโปเกมอนต่อไปนี้จะปรากฏในการต่อสู้แบบเรด\n\nการโจมตีระดับหนึ่งดาว\nCorphish*\nDwebble*\nClauncher*\n\nการโจมตีระดับสามดาว\nDhelmise*\nDondozo*\n\n*ถ้าโชคดี คุณอาจเจอตัวสีพิเศษก็ได้*\nการเผชิญหน้าในภารกิจการวิจัยภาคสนาม\nจะมีภารกิจวิจัยภาคสนามที่เกี่ยวข้องกับกิจกรรมต่างๆ ให้เลือกทำ!\n\nโปเกมอนต่อไปนี้จะพร้อมให้คุณพบเจอเมื่อคุณทำภารกิจวิจัยภาคสนามสำเร็จ!\n\nคอร์ฟิช*\nดเวเบิล*\nคลาวน์เซอร์*\n\nเทรนเนอร์บางคนอาจพบเจอกับสิ่งต่อไปนี้ด้วย\nDhelmise*\nKlawf\n\n*ถ้าโชคดี คุณอาจเจอตัวสีพิเศษก็ได้*\nการวิจัยแบบกำหนดเวลา\nจะมีภารกิจวิจัยแบบจำกัดเวลา 3 ภารกิจที่เกี่ยวข้องกับการจับโปเกมอน ซึ่งจะเปิดให้เล่นตลอดช่วงกิจกรรมตามตารางเวลาดังต่อไปนี้!\n\nวันอังคารที่ 6 มกราคม เวลา 10:00 น. ถึงวันพฤหัสบดีที่ 8 มกราคม พ.ศ. 2569 เวลา 10:00 น. ตามเวลาท้องถิ่น\n\nทำภารกิจวิจัยให้สำเร็จเพื่อพบกับโปเกมอนประจำกิจกรรมต่อไปนี้\n\nดเวเบิล*\nคลอว์ฟ\nวันพฤหัสบดีที่ 8 มกราคม เวลา 10:00 น. ถึงวันเสาร์ที่ 10 มกราคม พ.ศ. 2569 เวลา 10:00 น. ตามเวลาท้องถิ่น\n\nทำภารกิจวิจัยให้สำเร็จเพื่อพบกับโปเกมอนประจำกิจกรรมต่อไปนี้\n\nคอร์ฟิช*\nคลอว์ฟ\nวันเสาร์ที่ 10 มกราคม เวลา 10:00 น. ถึงวันอาทิตย์ที่ 11 มกราคม พ.ศ. 2569 เวลา 20:00 น. ตามเวลาท้องถิ่น\n\nทำภารกิจวิจัยให้สำเร็จเพื่อพบกับโปเกมอนประจำกิจกรรมต่อไปนี้\n\nตัวปล่อยจรวด*\nคลอว์ฟ\n*ถ้าโชคดี คุณอาจเจอตัวสีพิเศษก็ได้*\nการวิจัยแบบมีกำหนดเวลาและได้รับค่าตอบแทน\nในราคา 1.99 ดอลลาร์สหรัฐ (หรือราคาเทียบเท่าในสกุลเงินท้องถิ่นของคุณ) คุณจะสามารถเข้าถึงการวิจัยแบบจำกัดเวลาพิเศษเฉพาะกิจกรรมนี้ได้\n\nรางวัลจากการทำภารกิจวิจัยแบบจำกัดเวลา ได้แก่ สิ่งของต่อไปนี้\n\nบัตรผ่านการต่อสู้ระดับพรีเมียม 2 ใบ\nการเผชิญหน้ากับคอร์ฟิช ดเวเบิล คลอนเชอร์ เดลไมส์ และคลอว์ฟ\nและยังมีอีกมากมาย!\nโปรดทราบว่าภารกิจวิจัยแบบจำกัดเวลาจะหมดอายุลง ภารกิจที่เกี่ยวข้องกับภารกิจวิจัยแบบจำกัดเวลานี้จะต้องทำเสร็จและรับรางวัลก่อนวันอาทิตย์ที่ 11 มกราคม 2569 เวลา 20:00 น. ตามเวลาท้องถิ่น\n\nผู้เล่นสามารถซื้อและมอบตั๋วให้กับเพื่อนใน Pokémon GO ที่มีระดับมิตรภาพตั้งแต่ระดับ \"เพื่อนดี\" ขึ้นไปได้ โปรดทราบว่าการซื้อ—รวมถึงการซื้อให้ผู้เล่นคนอื่น—ไม่สามารถขอคืนเงินได้ (ยกเว้นในกรณีที่กฎหมายบังคับใช้และข้อยกเว้นที่ระบุไว้ในข้อกำหนดในการให้บริการ) ไม่สามารถซื้อตั๋วด้วย PokéCoins ได้\n\n*โปรดทราบว่าตั๋ววิจัยแบบจำกัดเวลา Pinch Perfect Premium Timed Research จะวางจำหน่ายในร้านค้าในเกมจนถึงวันที่ 11 มกราคม 2026 เวลา 20:00 น. เท่านั้น\n\nร้านค้าออนไลน์ Pokémon GO – กล่องตั๋วอัลตร้า Pinch Perfect\nชุดตั๋ว Pinch Perfect Ultra Ticket Box จะวางจำหน่ายในราคา 1.99 ดอลลาร์สหรัฐ (หรือราคาเทียบเท่าในสกุลเงินท้องถิ่นของคุณ) และประกอบด้วยตั๋วเข้าชมงานและลูกบอล Ultra Ball จำนวน 5 ลูก!', 'https://lh3.googleusercontent.com/oA5TgQgS0U-PZWEWY7miK-kD0vrxrBnWYl79JVxbtdr79yxvkXQaLohyBODc2x-F5FmpPLZ7hY6T5VlWIuF2KRYBl9yI3qUwNgp9=e365-pa-nu-w1920', '2025-12-22 07:04:18', 1);
INSERT INTO `events` (`id`, `title`, `description`, `image`, `created_at`, `created_by`) VALUES
(24, 'Dialga และเครื่องรางนำโชคกลับมาอีกครั้งใน GO Pass: เดือนมกราคม!', 'GO Pass: มกราคม\nตั้งแต่วันอังคารที่ 6 มกราคม เวลา 10:00 น. ถึงวันอังคารที่ 3 กุมภาพันธ์ เวลา 10:00 น. ตามเวลาท้องถิ่น GO Pass และ GO Pass Deluxe สำหรับเดือนมกราคมจะพร้อมให้ใช้งานใน Pokémon GO!\n\nGO Pass และ GO Pass Deluxe\nผู้เล่นทุกคนจะได้รับ GO Pass: เดือนมกราคมโดยอัตโนมัติในวันอังคารที่ 6 มกราคม เวลา 10:00 น. ตามเวลาท้องถิ่น และสามารถสะสม GO Points และเลื่อนระดับเพื่อรับรางวัลเพิ่มเติมได้จนถึงวันอังคารที่ 3 กุมภาพันธ์ เวลา 10:00 น. ตามเวลาท้องถิ่น\n\nนอกจากนี้ ตั้งแต่วันเสาร์ที่ 31 มกราคม เวลา 00:00 น. ถึงวันอาทิตย์ที่ 1 กุมภาพันธ์ เวลา 23:59 น. ตามเวลาท้องถิ่นคุณสามารถสะสม GO Points ได้ไม่จำกัดจำนวนต่อวัน!\n\nในราคา 7.99 ดอลลาร์สหรัฐ เทรนเนอร์สามารถอัปเกรดเป็น GO Pass Deluxe ซึ่งเป็นเวอร์ชันแบบชำระเงินของ GO Pass ที่มอบรางวัลที่ได้รับการอัปเกรดและความก้าวหน้าที่เร็วขึ้น\n\nในราคา 9.99 ดอลลาร์สหรัฐ* เทรนเนอร์สามารถอัปเกรดเป็น GO Pass Deluxe + 10 Ranks เพื่อรับ GO Points โดยอัตโนมัติเพียงพอที่จะเลื่อนระดับไปถึง Rank 11 ได้\n\nเมื่อคุณใช้งาน GO Pass Deluxe ไปเรื่อยๆ คุณจะสามารถรับรางวัลทั้งหมดจากทั้ง GO Pass ฟรีและ GO Pass Deluxe ได้ คุณสามารถอัปเกรดเป็น GO Pass Deluxe ได้ทุกเมื่อและยังคงรับรางวัลจากระดับที่ปลดล็อกไว้ก่อนหน้านี้ได้เช่นกัน\n\nรางวัลที่ปลดล็อกได้ใน GO Pass จะหมดอายุในวันพฤหัสบดีที่ 5 กุมภาพันธ์ เวลา 10:00 น. ตามเวลาท้องถิ่น ดังนั้นอย่าลืมรับรางวัลของคุณก่อนที่จะหมดอายุ!\n\n*ราคาทั้งหมดที่แสดงเป็นสกุลเงินดอลลาร์สหรัฐ หรือเทียบเท่าในสกุลเงินท้องถิ่นของคุณ\nร้านค้าออนไลน์ Pokémon GO\nบัตร GO Pass Deluxe ที่คุณซื้อผ่านทาง Pokémon GO Web Store จะเปิดใช้งานทันทีที่ GO Pass เริ่มใช้งาน\n\nเทรนเนอร์ที่อัปเกรดเป็นGO Pass Deluxe: มกราคมหรือGO Pass Deluxe: มกราคม + 10 Ranksบน Pokémon GO Web Store จะได้รับ Ultra Ball 10 ลูก, Max Revive 5 ชิ้น, Premium Battle Pass 1 ใบ และ Max Potion 5 ชิ้น เป็นของแถมเมื่อซื้อ\n\nหรือจะตุนของจำเป็นไปพร้อมกับการอัปเกรดของคุณด้วยGO Pass Deluxe: January + 10 Ranks Ultra Box ที่มีจำหน่ายเฉพาะบนเว็บไซต์เท่านั้น ซึ่งประกอบด้วย Ultra Ball 20 ลูก, Max Revive 10 ชิ้น, Max Potion 10 ชิ้น, Premium Battles Pass สองใบ, Incubator หนึ่งอัน และ Super Incubator หนึ่งอัน เป็นของแถมเมื่อซื้อ!\n\nโปเกมอนเด่นและรางวัล\nทำภารกิจใน GO Pass ให้สำเร็จเพื่อเพิ่มระดับ GO Pass ของคุณและรับรางวัลดังต่อไปนี้\n\nการเผชิญหน้ากับไดอัลก้า*\nฝุ่นดาว\nเอ็กซ์พี\nอนุภาคสูงสุด\nและยังมีของดีอีกมากมาย!\nเทรนเนอร์ที่อัปเกรดเป็น GO Pass Deluxe จะได้รับรางวัลต่อไปนี้ด้วย\n\nเครื่องรางนำโชค\nตู้ฟักไข่ซุปเปอร์หนึ่งตู้\nพบกับโปเกมอนเพิ่มเติมอีกมากมาย!\nไอเทมระดับพรีเมียม เช่น พรีเมียมแบทเทิลพาส, ธูปหอม, ตู้ฟักไข่, โมดูลล่อ และอื่นๆ อีกมากมาย!\nและยังมีของดีอีกมากมาย!\n*คุณอาจเจอตัวสีพิเศษ (Shiny) ด้วยก็ได้ ถ้าโชคดี!\n\nโบนัสความสำเร็จครั้งสำคัญ\nบรรลุเป้าหมายสำคัญต่างๆ บน GO Pass ของคุณเพื่อปลดล็อกโบนัสต่อไปนี้\n\nระดับ 1 – อันดับที่ 25\n\nเปิดของขวัญได้สูงสุด 40 ชิ้นต่อวัน\nรับของขวัญได้สูงสุด 125 ชิ้นต่อวันจากการหมุน PokéStop และ Photo Disc ใน Gym\nสามารถเก็บของขวัญได้อีก 10 ชิ้นในกระเป๋าใส่ของของคุณ\nระดับ 2 – อันดับ 50\n\nระยะเวลาการใช้งานธูปผจญภัยประจำวัน 2 เท่า\nระดับ 3 – อันดับ 75\n\nรางวัลเพิ่มเติมสำหรับการพิชิตการบุกโจมตีแบบตัวต่อตัวและการต่อสู้ระดับสูงสุด\nอัปเกรดเป็น GO Pass Deluxe เพื่อเพิ่มโบนัสต่อไปนี้:\n\nระดับ 1 – อันดับที่ 25\n\nเปิดของขวัญได้สูงสุด 50 ชิ้นต่อวัน\nรับของขวัญได้สูงสุด 150 ชิ้นต่อวันจากการหมุน PokéStop และ Photo Disc ใน Gym\nสามารถเก็บของขวัญได้มากถึง 20 ชิ้นในถุงใส่ของของคุณ\nเครื่องรางนำโชค\nเครื่องรางนำโชคจะกลับมาอีกครั้งในฐานะรางวัลสุดท้ายใน GO Pass Deluxe ประจำเดือนนี้\n\nเครื่องรางนำโชคเป็นไอเทมที่ใช้ได้เพียงครั้งเดียว สามารถใช้เปลี่ยนเพื่อนหนึ่งคนในรายชื่อเพื่อนของคุณให้กลายเป็นเพื่อนนำโชคได้ เมื่อใช้แล้ว เครื่องรางนำโชคจะเปลี่ยนสถานะของคุณและเพื่อนที่คุณเลือกให้เป็นเพื่อนนำโชค แม้ว่าคุณจะยังไม่ได้เป็นเพื่อนสนิทกันก็ตาม! เมื่อคุณเป็นเพื่อนนำโชคกับใครสักคนแล้ว ครั้งต่อไปที่คุณแลกเปลี่ยนโปเกมอนกัน โปเกมอนทั้งสองตัวจะกลายเป็นโปเกมอนนำโชค หลังจากแลกเปลี่ยนเสร็จ สถานะเพื่อนนำโชคของคุณจะถูกล้างออก\n\nไอเทมสุดพิเศษนี้จะอยู่ในกระเป๋าไอเทมของคุณได้เพียงช่วงเวลาจำกัดเท่านั้น อย่าลืมใช้มันนะ! เครื่องรางนำโชคที่ได้รับจาก GO Pass: เดือนมกราคม จะหมดอายุในวันอาทิตย์ที่ 8 กุมภาพันธ์ 2026 เวลา 23:59 น. ตามเวลาท้องถิ่น ไม่ว่าคุณจะรับมันเมื่อไหร่ก็ตาม\n\nคุณต้องมีสถานะอย่างน้อยเป็นเพื่อนระดับ Great กับเทรนเนอร์ที่คุณต้องการใช้เครื่องรางนำโชคด้วย คุณไม่สามารถใช้เครื่องรางนำโชคกับเทรนเนอร์ที่คุณมีสถานะเป็นเพื่อนระดับ Lucky Friends อยู่แล้วได้ การใช้เครื่องรางนำโชคกับเพื่อนไม่ได้เปลี่ยนแปลงระยะทางที่คุณสามารถทำการแลกเปลี่ยนได้ หากคุณไม่ต้องการอนุญาตให้เทรนเนอร์คนอื่นใช้เครื่องรางนำโชคกับคุณ คุณสามารถปิดใช้งานสิทธิ์นี้ได้ในหน้าการตั้งค่าของคุณ', 'https://lh3.googleusercontent.com/r4r8-Lwf4V4L6bOApnwtV9RDxaOOLMyrIiPtnjEDSdosCigLUxCQ55eHRwqHdJ6prOkWq5jhCiL-nWC6I7JeTtYIHgLHEht11Pkj=e365-pa-nu-w1920', '2025-12-22 07:04:38', 1),
(25, 'ชาร์จพลังเพื่อต้อนรับอีเวนต์กำลังไฟสูงและปลดล็อกการเปิดตัวของไคเด็น!', 'กำลังไฟสูง\nวันอังคารที่ 13 มกราคม เวลา 10.00 น. ถึงวันอาทิตย์ที่ 18 มกราคม 2026 เวลา 20.00 น. ตามเวลาไทย\n\nโบนัสอีเวนต์\nโอกาสเพิ่มขึ้นที่จะได้ฟักไข่ซุพีคาสีแตกต่าง\nคำท้าสำหรับทั่วโลก\nคำท้าสำหรับทั่วโลกจะจัดขึ้นตลอดอีเวนต์กำลังไฟสูง! สำรวจพร้อมไปกับเทรนเนอร์ทั่วโลกเพื่อปลดล็อกโบนัสให้ทุกคนได้เพลิดเพลิน เมื่อทำภารกิจเสร็จสิ้นแล้ว โบนัสพิเศษจะถูกปลดล็อกสำหรับช่วงเวลาที่เหลือของอีเวนต์และคำท้าสำหรับทั่วโลกถัดไปจะเริ่มต้นขึ้น\n\nรางวัลระดับที่ 1\n2× XP จากการจับโปเกมอน\nรางวัลระดับที่ 2\n2× สตาร์ดัสต์จากการจับโปเกมอน\nโปเกมอนนกนางแอ่นทะเล ไคเด็นและร่างวิวัฒนาการของมัน ไทไคเด็นจะเปิดตัวใน Pokémon GO เป็นครั้งแรกในธรรมชาติและงานวิจัยภาคสนาม!\nคุณสามารถใช้ลูกอมไคเด็น 50 เม็ดเพื่อวิวัฒนาการไคเด็นเป็นไทไคเด็นได้\nรางวัลระดับที่ 3\n2× XP จากการฟักไข่โปเกมอน\n2× สตาร์ดัสต์จากการฟักไข่โปเกมอน\nเผชิญหน้าในธรรมชาติ\nอาจได้เผชิญหน้ากับโปเกมอนธีมอีเวนต์ในธรรมชาติ รวมถึง ชอนชี*, เอลิคิเทล*, ซุพีคา* และโปเกมอนอื่น ๆ อีกมากมาย! และอาจได้เผชิญหน้ากับโคลิงก์* ด้วย!\n\n*หากโชคดี อาจเจอตัวสีแตกต่างก็ได้!\nไข่\nโปเกมอนต่อไปนี้จะฟักออกจากไข่ 2 กม.\n\nพิชู*\nเอเลคิด*\nเอเลซัน*\nซุพีคา*\n\n* หากโชคดี อาจเจอตัวสีแตกต่างก็ได้!\nการเผชิญหน้างานวิจัยภาคสนาม\nภารกิจงานวิจัยภาคสนามธีมอีเวนต์จะพร้อมให้ใช้งาน\n\nทำภารกิจงานวิจัยภาคสนามให้เสร็จสิ้นเพื่อรับการเผชิญหน้ากับโปเกมอนธีมอีเวนต์\n\nงานวิจัยแบบจำกัดเวลาแบบเสียเงิน\nในราคา US$1.99 (หรือราคาเทียบเท่าสกุลเงินท้องถิ่นของคุณ) คุณจะสามารถเข้าถึงงานวิจัยแบบจำกัดเวลาเฉพาะอีเวนต์ การซื้อตั๋วใบนี้จะทำให้ได้รับโบนัสต่อไปนี้ในระหว่างอีเวนต์กำลังไฟสูง\n\nระยะทางฟักไข่ 1/2 เมื่อไข่ถูกวางไว้ในเครื่องฟักไข่ในระหว่างช่วงเวลาอีเวนต์\nงานวิจัยแบบจำกัดเวลามีดังต่อไปนี้\n\nเครื่องฟักไข่ 1 เครื่อง\nเครื่องฟักไข่ชั้นเยี่ยม 1 เครื่อง\nการเผชิญหน้ากับซุพีคา\nและอีกมากมาย!\nเทรนเนอร์ทุกคนจะสามารถซื้อและมอบตั๋วเป็นของขวัญให้กับเพื่อน Pokémon GO ของพวกเขาที่มีระดับความสนิทสนมเป็นเพื่อนสนิทขึ้นไปอีกด้วย โปรดทราบว่าการซื้อ—รวมถึงการซื้อให้เทรนเนอร์คนอื่น—ไม่สามารถขอคืนเงินได้ (ขึ้นอยู่กับกฎหมายที่บังคับใช้และข้อยกเว้นที่กำหนดไว้ในข้อกำหนดในการให้บริการ) ไม่สามารถใช้โปเกคอยน์ซื้อตั๋วได้\n\nโปรดทราบว่างานวิจัยแบบจำกัดเวลามีวันหมดอายุ ภารกิจที่เกี่ยวข้องกับงานวิจัยแบบจำกัดเวลานี้จะต้องเสร็จสิ้นและต้องรับรางวัลก่อนวันอาทิตย์ที่ 18 มกราคม 2026 เวลา 20.00 น. ตามเวลาไทย', 'https://lh3.googleusercontent.com/BZh6ZEXetBW4bU6LFokwo5F0fWk1h2p823B4_MHLrwFEC8xze1M40qO-TKOQU8Yo6l2Ntot3gvLRgwgXxD0mWR90nwTs-F0WvPM=e365-pa-nu-w1920', '2026-01-14 09:31:12', 1);
