INSERT INTO `notifications` (`id`, `title`, `message`, `target`, `user_id`, `room_id`, `sent_by`, `status`, `schedule_at`, `schedule_status`, `created_at`, `updated_at`) VALUES
(24, 'กิจกรรมบอส Gmax Snorlax เริ่มแล้ว', 'เวลา 14:00 - 17:00 น.', 'all', NULL, NULL, 1, 'sended', NULL, NULL, '2025-12-12 08:25:06', NULL),
(25, 'ทดสอบ บอร์ดแคส', 'เวลา 14:00 - 17:00 น.', 'all', NULL, NULL, 1, 'sended', NULL, NULL, '2025-12-16 09:56:51', NULL),
(26, 'กิจกรรม Community Day', 'XP x2 ตลอดการจับ มาจับกันเถอะ', 'all', NULL, NULL, 1, 'sended', NULL, NULL, '2025-12-16 15:04:17', NULL),
(28, '🕕 Raid Hour วันนี้! บอส 5 ดาวเกิดเต็มแมพ', 'เตรียมปาร์ตี้ให้พร้อม! 18:00 น. นี้ เจอกัน หาเพื่อนช่วยตีบอส หรือสร้างห้องรอเพื่อนได้เลยที่ Pogopartyth 🚀', 'all', NULL, NULL, 1, 'sended', NULL, NULL, '2025-12-17 06:07:35', NULL),
(29, '❄️ ลมหนาวมาแล้ว พร้อมบอสใหม่!', 'กิจกรรม Winter Holiday เริ่มแล้ว! อย่าพลาดโอกาสจับโปเกมอนคอสตูมพิเศษและบอสน้ำแข็งสุดแกร่ง เข้ามาเช็คห้องว่างเลย! ☃️', 'all', NULL, NULL, 1, 'sended', NULL, NULL, '2025-12-20 09:04:51', NULL),
(30, '🔥 ห้องเต็มไวมาก! เทรนเนอร์รออยู่', 'เพื่อนๆ กำลังหาคนช่วยตีบอสอยู่เพียบ! ขาดอีกแค่ไม่กี่คนก็เริ่มตีได้แล้ว เข้ามาจองที่ด่วน 🏃💨', 'all', NULL, NULL, 1, 'sended', NULL, NULL, '2025-12-23 07:43:21', NULL),
(31, '⚔️ ได้เวลาตีบอสแล้ว!', 'เพื่อนๆ กำลังหาคนช่วยตีบอสอยู่เพียบ! ขาดอีกแค่ไม่กี่คนก็เริ่มตีได้แล้ว เข้ามาจองที่ด่วน 🏃💨', 'all', NULL, NULL, 1, 'sended', NULL, NULL, '2025-12-23 07:49:04', NULL),
(33, 'เย็นนี้ 6 โมง! น้องแมวน้ำ Spheal กลิ้งมาแจก XP', 'Spotlight Hour วันนี้พบกับ Spheal (ชิมาซึ) พร้อมโบนัส XP x2 เมื่อวิวัฒนาการ! 📈 ใครดองของไว้เตรียมกดยาวๆ จบแล้วมาหาเพื่อนตีบอสต่อได้เลย!', 'all', NULL, NULL, 1, 'sended', NULL, NULL, '2025-12-23 08:11:37', NULL),
(34, '⚡️ Zekrom มังกรสายฟ้า กลับมาแล้ว!', 'บอส 5 ดาวตัวใหม่ Zekrom และเมก้า Mega Glalie ❄️ เริ่มเกิดแล้ว! ใครยังไม่มีตัว หรือตามล่าไชนี่เท่ๆ เข้ามาจองห้องตีบอสด่วน เพื่อนรอเพียบ!', 'all', NULL, NULL, 1, 'sended', NULL, NULL, '2025-12-23 08:20:44', NULL),
(37, '🎄 โค้งสุดท้าย Winter Holiday Part 1', 'พรุ่งนี้กิจกรรมจะเปลี่ยนพาร์ทแล้ว! รีบเก็บตกโปเกมอนคอสตูมชุดคริสต์มาสก่อนหมดเวลา 🎅 แล้วมาจัดปาร์ตี้ตีบอสส่งท้ายปีกันที่ Pogopartyth', 'all', NULL, NULL, 1, 'sended', NULL, NULL, '2025-12-24 13:20:27', NULL),
(42, '🎁 แกะกล่องของขวัญ! Winter Holiday Part 2 เริ่มแล้ว', 'เหล่าโปเกมอนสวมชุดคริสต์มาสชุดใหม่มาแล้ว! 🎄 อย่าลืมเข้ามาหาเพื่อนตีบอสเก็บ Candy ส่งท้ายปีกันนะ ห้องว่างเพียบ!', 'all', NULL, NULL, 1, 'schedule', '2025-12-26 13:00:00', 'success', '2025-12-26 10:40:47', NULL),
(43, '🔥 ศุกร์สิ้นปี... ต้องมีตัวเทพ!', 'ทำงานวันสุดท้ายของสัปดาห์แล้ว มาปลดปล่อยพลังตีบอสกันเถอะ! ⚡️ Zekrom (หรือบอสปัจจุบัน) ไชนี่รอคุณอยู่ เข้ามาจอยปาร์ตี้เลย', 'all', NULL, NULL, 1, 'schedule', '2025-12-26 17:30:00', 'success', '2025-12-26 10:41:21', NULL),
(44, '❄️ หนาวนี้ไม่เหงา... มาหาเพื่อนตีบอสกัน', 'ขาดคนช่วยตีบอสใช่ไหม? หรืออยากหาเพื่อนส่งของขวัญ? 🎁 เข้า Pogopartyth ตอนนี้ เจอเพื่อนเทรนเนอร์ใจดีรออยู่แน่นอน!', 'all', NULL, NULL, 1, 'schedule', '2025-12-27 08:00:00', 'success', '2025-12-26 10:42:01', NULL),
(50, 'asdasd', 'asd', 'all', NULL, NULL, 1, 'daily', NULL, 'success', '2026-03-05 11:36:18', '2026-03-05 11:49:08'),
(51, 'สัปดาห์ใหม่ เริ่มแล้ว', 'กิจกรรมใหม่ รอคุณอยู่ เช็คข้อมูลแล้วไปลุยกัน', 'all', NULL, NULL, 1, 'weekly', NULL, 'success', '2026-03-05 11:51:33', '2026-03-05 11:51:51');
